import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../constants';

interface ChatInputProps {
  onSend: (message: string) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSend, disabled }) => {
  const [input, setInput] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'inherit';
      const scrollHeight = textareaRef.current.scrollHeight;
      textareaRef.current.style.height = `${Math.min(scrollHeight, 200)}px`;
    }
  }, [input]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !disabled) {
      onSend(input.trim());
      setInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div className="border-t border-gray-100 bg-white p-4 pb-8 md:pb-4 shadow-2xl">
      <form onSubmit={handleSubmit} className="relative max-w-4xl mx-auto">
        <textarea
          ref={textareaRef}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="How can I help you today?"
          disabled={disabled}
          className="w-full pl-4 pr-12 py-3 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all resize-none bg-gray-50 text-sm leading-relaxed scrollbar-hide"
          rows={1}
        />
        <button
          type="submit"
          disabled={!input.trim() || disabled}
          className={`absolute right-2 bottom-2 p-2 rounded-lg transition-all ${
            input.trim() && !disabled 
              ? 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-500/30' 
              : 'bg-gray-100 text-gray-400 cursor-not-allowed'
          }`}
        >
          <Icons.Send />
        </button>
      </form>
      <p className="mt-2 text-center text-[10px] text-gray-400">
        AI responses are generated by Gemini and may sometimes be inaccurate.
      </p>
    </div>
  );
};

export default ChatInput;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState } from './types';
import { gemini } from './services/geminiService';
import { Icons } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>({
    messages: [
      {
        id: '1',
        role: 'assistant',
        content: "Hi there! I'm your friendly AI assistant. How can I help you today?",
        timestamp: Date.now(),
      }
    ],
    isLoading: false,
    error: null,
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [state.messages, scrollToBottom]);

  const handleSendMessage = async (content: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: Date.now(),
    };

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, userMessage],
      isLoading: true,
      error: null,
    }));

    try {
      const assistantId = (Date.now() + 1).toString();
      const initialAssistantMessage: Message = {
        id: assistantId,
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
      };

      setState(prev => ({
        ...prev,
        messages: [...prev.messages, initialAssistantMessage],
      }));

      let fullContent = '';
      for await (const chunk of gemini.streamMessage(content)) {
        fullContent += chunk;
        setState(prev => {
          const newMessages = [...prev.messages];
          const lastMsgIndex = newMessages.findIndex(m => m.id === assistantId);
          if (lastMsgIndex !== -1) {
            newMessages[lastMsgIndex] = {
              ...newMessages[lastMsgIndex],
              content: fullContent,
            };
          }
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        error: "Oops! Something went wrong while connecting to the AI. Please try again.",
      }));
    } finally {
      setState(prev => ({ ...prev, isLoading: false }));
    }
  };

  const resetConversation = () => {
    gemini.resetChat();
    setState({
      messages: [
        {
          id: Date.now().toString(),
          role: 'assistant',
          content: "Chat reset! How else can I help you?",
          timestamp: Date.now(),
        }
      ],
      isLoading: false,
      error: null,
    });
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 max-w-5xl mx-auto shadow-2xl relative overflow-hidden">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 bg-white border-b border-gray-100 z-10 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
            <Icons.Bot />
          </div>
          <div>
            <h1 className="font-bold text-gray-800 leading-tight">Friendly Buddy</h1>
            <div className="flex items-center gap-1.5">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-gray-500 font-medium uppercase tracking-wider">Online</span>
            </div>
          </div>
        </div>
        <button 
          onClick={resetConversation}
          className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
          title="Reset Chat"
        >
          <Icons.Refresh />
        </button>
      </header>

      {/* Main Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 md:p-6 space-y-2 scrollbar-hide">
        {state.messages.map((msg) => (
          <ChatMessage key={msg.id} message={msg} />
        ))}
        {state.isLoading && state.messages[state.messages.length - 1].role === 'user' && (
          <div className="flex justify-start gap-3 animate-pulse">
            <div className="w-8 h-8 rounded-full bg-blue-50 flex items-center justify-center">
              <Icons.Bot />
            </div>
            <div className="bg-white border border-gray-100 rounded-2xl rounded-tl-none px-4 py-3 shadow-sm">
              <div className="flex gap-1">
                <span className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce"></span>
                <span className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce delay-150"></span>
                <span className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce delay-300"></span>
              </div>
            </div>
          </div>
        )}
        {state.error && (
          <div className="p-4 rounded-xl bg-red-50 border border-red-100 text-red-600 text-sm text-center">
            {state.error}
          </div>
        )}
        <div ref={messagesEndRef} />
      </main>

      {/* Footer / Input Area */}
      <ChatInput onSend={handleSendMessage} disabled={state.isLoading} />
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, GenerateContentResponse, Modality } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

export class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    this.chatSession = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
        topK: 64,
      },
    });
  }

  async *streamMessage(message: string): AsyncGenerator<string> {
    try {
      const result = await this.chatSession.sendMessageStream({ message });

      for await (const chunk of result) {
        const responseChunk = chunk as GenerateContentResponse;
        const text = responseChunk.text;
        if (text) {
          yield text;
        }
      }
    } catch (error) {
      console.error("Gemini stream error:", error);
      throw error;
    }
  }

  async generateSpeech(text: string): Promise<string | undefined> {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say this naturally and warmly: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });
      return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    } catch (error) {
      console.error("Speech generation error:", error);
      return undefined;
    }
  }

  resetChat() {
    this.chatSession = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });
  }

  decodeBase64(base64: string): Uint8Array {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  async decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number = 24000,
    numChannels: number = 1,
  ): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }
}

export const gemini = new GeminiService();

import React, { useState } from 'react';
import { Message } from '../types';
import { Icons } from '../constants';

interface ChatMessageProps {
  message: Message;
  onSpeak?: (text: string) => void;
  isSpeaking?: boolean;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message, onSpeak, isSpeaking }) => {
  const isUser = message.role === 'user';
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'} group animate-in fade-in slide-in-from-bottom-2 duration-300`}>
      <div className={`flex max-w-[85%] md:max-w-[75%] ${isUser ? 'flex-row-reverse' : 'flex-row'} gap-3`}>
        <div className={`flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center shadow-sm ${isUser ? 'bg-gray-200' : 'bg-blue-100'}`}>
          {isUser ? <Icons.User /> : <Icons.Bot />}
        </div>

        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          <div className={`relative px-4 py-3 rounded-2xl text-[14px] leading-relaxed shadow-sm transition-all border ${
            isUser 
              ? 'bg-blue-600 text-white border-blue-500 rounded-tr-none' 
              : 'bg-white text-gray-800 border-gray-100 rounded-tl-none hover:border-blue-100'
          }`}>
            <div className="whitespace-pre-wrap">{message.content}</div>
          </div>

          <div className={`flex gap-3 mt-2 px-1 items-center opacity-0 group-hover:opacity-100 transition-opacity duration-200 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
            <span className="text-[10px] text-gray-400 font-medium">
              {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>

            <button 
              onClick={handleCopy}
              className="text-gray-400 hover:text-blue-500 transition-colors"
              title="Copy to clipboard"
            >
              {copied ? <Icons.Check /> : <Icons.Copy />}
            </button>

            {!isUser && onSpeak && (
              <button 
                onClick={() => onSpeak(message.content)}
                disabled={isSpeaking}
                className={`transition-colors ${isSpeaking ? 'text-blue-500 animate-pulse' : 'text-gray-400 hover:text-blue-500'}`}
                title="Listen to response"
              >
                <Icons.Speaker />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState } from './types';
import { gemini } from './services/geminiService';
import { Icons } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>({
    messages: [
      {
        id: '1',
        role: 'assistant',
        content: "Hi there! I'm your friendly AI assistant. How can I help you today?",
        timestamp: Date.now(),
      }
    ],
    isLoading: false,
    error: null,
  });

  const [isSpeaking, setIsSpeaking] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [state.messages, scrollToBottom]);

  const handleSpeak = async (messageId: string, text: string) => {
    if (isSpeaking) {
      currentSourceRef.current?.stop();
      setIsSpeaking(null);
      return;
    }

    setIsSpeaking(messageId);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      const base64Audio = await gemini.generateSpeech(text);

      if (base64Audio) {
        const audioData = gemini.decodeBase64(base64Audio);
        const buffer = await gemini.decodeAudioData(audioData, ctx);

        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(null);

        currentSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(null);
      }
    } catch (err) {
      console.error("Speech error:", err);
      setIsSpeaking(null);
    }
  };

  const handleSendMessage = async (content: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: Date.now(),
    };

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, userMessage],
      isLoading: true,
      error: null,
    }));

    try {
      const assistantId = (Date.now() + 1).toString();
      const initialAssistantMessage: Message = {
        id: assistantId,
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
      };

      setState(prev => ({
        ...prev,
        messages: [...prev.messages, initialAssistantMessage],
      }));

      let fullContent = '';
      for await (const chunk of gemini.streamMessage(content)) {
        fullContent += chunk;
        setState(prev => {
          const newMessages = [...prev.messages];
          const lastMsgIndex = newMessages.findIndex(m => m.id === assistantId);
          if (lastMsgIndex !== -1) {
            newMessages[lastMsgIndex] = {
              ...newMessages[lastMsgIndex],
              content: fullContent,
            };
          }
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        error: "Oops! Something went wrong while connecting to the AI. Please try again.",
      }));
    } finally {
      setState(prev => ({ ...prev, isLoading: false }));
    }
  };

  const resetConversation = () => {
    gemini.resetChat();
    currentSourceRef.current?.stop();
    setIsSpeaking(null);
    setState({
      messages: [
        {
          id: Date.now().toString(),
          role: 'assistant',
          content: "Chat reset! How else can I help you today?",
          timestamp: Date.now(),
        }
      ],
      isLoading: false,
      error: null,
    });
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 max-w-4xl mx-auto shadow-2xl relative overflow-hidden">
      <header className="flex items-center justify-between px-6 py-4 bg-white border-b border-gray-100 z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
            <Icons.Bot />
          </div>
          <div>
            <h1 className="font-bold text-gray-800 leading-tight">Friendly Buddy</h1>
            <div className="flex items-center gap-1.5">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Active</span>
            </div>
          </div>
        </div>
        <button 
          onClick={resetConversation}
          className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
          title="Reset conversation"
        >
          <Icons.Refresh />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-6 space-y-2 scrollbar-hide bg-[#f8fafc]">
        {state.messages.map((msg) => (
          <ChatMessage 
            key={msg.id} 
            message={msg} 
            onSpeak={(text) => handleSpeak(msg.id, text)}
            isSpeaking={isSpeaking === msg.id}
          />
        ))}
        {state.isLoading && state.messages[state.messages.length - 1].role === 'user' && (
          <div className="flex justify-start gap-3 animate-pulse mb-6">
            <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center">
              <Icons.Bot />
            </div>
            <div className="bg-white border border-gray-100 rounded-2xl rounded-tl-none px-4 py-3 shadow-sm">
              <div className="flex gap-1.5 py-1">
                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
              </div>
            </div>
          </div>
        )}
        {state.error && (
          <div className="p-4 rounded-xl bg-red-50 border border-red-100 text-red-600 text-sm text-center font-medium">
            {state.error}
          </div>
        )}
        <div ref={messagesEndRef} className="h-4" />
      </main>

      <ChatInput onSend={handleSendMessage} disabled={state.isLoading} />
    </div>
  );
};

export default App;

{
  "name": "CYBERGUARD AI",
  "description": "Ethical cybersecurity assistant with integrated authentication and subscription logic.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export type Role = 'user' | 'assistant';

export type PlanType = 'FREE' | 'BASIC' | 'PRO';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: number;
}

export interface User {
  id: string;
  username: string;
  email: string;
  plan: PlanType;
  createdDate: number;
}

export interface ChatState {
  messages: Message[];
  isLoading: boolean;
  error: string | null;
}

export interface AuthState {
  user: User | null;
  sessionToken: string | null;
}

import React, { useState } from 'react';
import { Icons } from '../constants';
import { User, PlanType } from '../types';

interface AuthModalProps {
  onSuccess: (user: User) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isSignUp) {
      if (!formData.username || !formData.email || !formData.password) {
        setError('All fields are mandatory.');
        return;
      }
      if (!formData.email.includes('@')) {
        setError('Invalid email format.');
        return;
      }
      if (formData.password.length < 8) {
        setError('Password must be at least 8 characters.');
        return;
      }
      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match.');
        return;
      }

      const newUser: User = {
        id: Math.random().toString(36).substr(2, 9),
        username: formData.username,
        email: formData.email,
        plan: 'FREE',
        createdDate: Date.now()
      };

      const users = JSON.parse(localStorage.getItem('cyber_users') || '[]');
      if (users.find((u: any) => u.email === formData.email)) {
        setError('User already exists.');
        return;
      }

      users.push({ ...newUser, password: formData.password });
      localStorage.setItem('cyber_users', JSON.stringify(users));
      onSuccess(newUser);
    } else {
      const users = JSON.parse(localStorage.getItem('cyber_users') || '[]');
      const user = users.find((u: any) => u.email === formData.email && u.password === formData.password);

      if (user) {
        onSuccess({
          id: user.id,
          username: user.username,
          email: user.email,
          plan: user.plan || 'FREE',
          createdDate: user.createdDate
        });
      } else {
        setError('Invalid credentials.');
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-emerald-500/30 w-full max-w-md rounded-2xl shadow-2xl shadow-emerald-500/10 overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="bg-emerald-500/10 p-6 border-b border-emerald-500/20 text-center">
          <div className="flex justify-center mb-3">
            <div className="w-12 h-12 bg-emerald-500 rounded-full flex items-center justify-center text-slate-900">
              <Icons.Shield />
            </div>
          </div>
          <h2 className="text-xl font-bold text-emerald-400 font-mono">
            {isSignUp ? 'INITIALIZING PROTOCOL' : 'SECURE LOGIN'}
          </h2>
          <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest">Node Connection Authentication</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-4">
          {error && (
            <div className="bg-red-500/10 border border-red-500/30 text-red-400 p-3 rounded-lg text-xs font-medium animate-pulse">
              [ERROR]: {error}
            </div>
          )}

          {isSignUp && (
            <div>
              <label className="block text-[10px] text-slate-500 font-bold uppercase mb-1 tracking-wider">Username</label>
              <input
                type="text"
                placeholder="Agent47"
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all"
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          <div>
            <label className="block text-[10px] text-slate-500 font-bold uppercase mb-1 tracking-wider">Email Address</label>
            <input
              type="email"
              placeholder="operator@secure.node"
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all font-mono"
              value={formData.email}
              onChange={e => setFormData({ ...formData, email: e.target.value })}
            />
          </div>

          <div>
            <label className="block text-[10px] text-slate-500 font-bold uppercase mb-1 tracking-wider">Password</label>
            <input
              type="password"
              placeholder="••••••••"
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all"
              value={formData.password}
              onChange={e => setFormData({ ...formData, password: e.target.value })}
            />
          </div>

          {isSignUp && (
            <div>
              <label className="block text-[10px] text-slate-500 font-bold uppercase mb-1 tracking-wider">Confirm Password</label>
              <input
                type="password"
                placeholder="••••••••"
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all"
                value={formData.confirmPassword}
                onChange={e => setFormData({ ...formData, confirmPassword: e.target.value })}
              />
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold py-3 rounded-lg transition-all shadow-lg shadow-emerald-500/20 active:scale-95 text-sm"
          >
            {isSignUp ? 'SIGN UP' : 'ACCESS TERMINAL'}
          </button>

          <div className="text-center mt-4">
            <button
              type="button"
              onClick={() => setIsSignUp(!isSignUp)}
              className="text-[10px] text-slate-400 hover:text-emerald-400 uppercase tracking-tighter"
            >
              {isSignUp ? 'Already registered? Login here' : 'New operator? Request registration'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

