import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { Icons, PLANS } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem('cyber_session');
    return stored ? JSON.parse(stored) : null;
  });

  const [chatState, setChatState] = useState<ChatState>({
    messages: [
      {
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: INITIALIZING CYBERGUARD AI PROTOCOL...\n\nGreetings, Operative. I am your specialized cybersecurity node. I can provide guidance on digital safety, ethical security education, and data protection.\n\nPlease authenticate to proceed with full assistance.",
        timestamp: Date.now(),
      }
    ],
    isLoading: false,
    error: null,
  });

  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [chatState.messages, scrollToBottom]);

  const handleAuthSuccess = (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('cyber_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);

    setChatState(prev => ({
      ...prev,
      messages: [
        ...prev.messages,
        {
          id: Date.now().toString(),
          role: 'assistant',
          content: `[AUTH SUCCESS]: Access granted for @${authenticatedUser.username}.\nCurrent Plan: ${authenticatedUser.plan}.\nHow can I assist your security operation today?`,
          timestamp: Date.now(),
        }
      ]
    }));
  };

  const handleSignOut = () => {
    setUser(null);
    localStorage.removeItem('cyber_session');
    gemini.resetChat();
    setChatState({
      messages: [{
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: SESSION TERMINATED. Login required for assistance.",
        timestamp: Date.now(),
      }],
      isLoading: false,
      error: null
    });
  };

  const handleUpgrade = (newPlan: PlanType) => {
    if (!user) return;
    const updatedUser = { ...user, plan: newPlan };
    setUser(updatedUser);
    localStorage.setItem('cyber_session', JSON.stringify(updatedUser));

    // Update the master user list in "database"
    const users = JSON.parse(localStorage.getItem('cyber_users') || '[]');
    const userIdx = users.findIndex((u: any) => u.email === user.email);
    if (userIdx !== -1) {
      users[userIdx].plan = newPlan;
      localStorage.setItem('cyber_users', JSON.stringify(users));
    }

    setShowPlans(false);
    setChatState(prev => ({
      ...prev,
      messages: [
        ...prev.messages,
        {
          id: Date.now().toString(),
          role: 'assistant',
          content: `[PLAN UPDATED]: Protocol migrated to ${newPlan}. All tier-specific features are now active.`,
          timestamp: Date.now(),
        }
      ]
    }));
  };

  const handleSendMessage = async (content: string) => {
    if (!user) {
      setShowAuth(true);
      return;
    }

    // Simple plan restriction logic
    if (user.plan === 'FREE' && chatState.messages.filter(m => m.role === 'user').length >= 5) {
       setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: Date.now().toString(),
            role: 'user',
            content,
            timestamp: Date.now()
          },
          {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "[WARNING]: FREE TIER QUOTA EXCEEDED. Please upgrade to BASIC or PRO plan for unlimited security analysis.",
            timestamp: Date.now(),
          }
        ]
      }));
      return;
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: Date.now(),
    };

    setChatState(prev => ({
      ...prev,
      messages: [...prev.messages, userMsg],
      isLoading: true,
      error: null,
    }));

    try {
      const assistantId = (Date.now() + 1).toString();
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, { id: assistantId, role: 'assistant', content: '', timestamp: Date.now() }],
      }));

      let fullResponse = "";
      for await (const chunk of gemini.streamMessage(content)) {
        fullResponse += chunk;
        setChatState(prev => {
          const newMessages = [...prev.messages];
          const idx = newMessages.findIndex(m => m.id === assistantId);
          if (idx !== -1) {
            newMessages[idx] = { ...newMessages[idx], content: fullResponse };
          }
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err) {
      setChatState(prev => ({
        ...prev,
        error: "[ERROR]: Connection to Cyber Node timed out. Check network integrity.",
      }));
    } finally {
      setChatState(prev => ({ ...prev, isLoading: false }));
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950/40 backdrop-blur-sm max-w-5xl mx-auto shadow-[0_0_100px_rgba(0,0,0,0.5)] border-x border-slate-900 relative">

      {/* Top Banner */}
      <div className="bg-emerald-500 text-slate-950 text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em]">
        Cyberguard Secure Communication Interface // Alpha Version 1.0.4
      </div>

      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 bg-slate-900/50 border-b border-slate-800 z-10">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-950 border border-emerald-500/40 rounded-lg flex items-center justify-center text-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
            <Icons.Shield />
          </div>
          <div>
            <h1 className="font-bold text-slate-50 tracking-tight font-mono">CYBERGUARD_AI</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,1)]"></span>
              <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Connection Stable</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {user ? (
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPlans(true)}
                className="hidden md:flex flex-col items-end px-3 py-1.5 rounded-lg border border-slate-800 bg-slate-950/50 hover:border-emerald-500/30 transition-all"
              >
                <span className="text-[9px] text-slate-500 font-bold uppercase tracking-tighter">Current Plan</span>
                <span className="text-[11px] text-emerald-400 font-bold font-mono">{user.plan}</span>
              </button>

              <div className="h-8 w-[1px] bg-slate-800 hidden md:block"></div>

              <div className="flex flex-col items-end">
                <span className="text-[10px] text-slate-100 font-bold font-mono">@{user.username}</span>
                <button 
                  onClick={handleSignOut}
                  className="text-[9px] text-red-400/70 hover:text-red-400 flex items-center gap-1 uppercase tracking-widest font-bold"
                >
                  Terminate Session
                </button>
              </div>
            </div>
          ) : (
            <button 
              onClick={() => setShowAuth(true)}
              className="px-6 py-2 bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold rounded-lg text-xs transition-all active:scale-95 shadow-lg shadow-emerald-500/20"
            >
              INITIALIZE LOGIN
            </button>
          )}
        </div>
      </header>

      {/* Main Terminal */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map((msg) => (
          <ChatMessage key={msg.id} message={msg} />
        ))}
        {chatState.isLoading && (
          <div className="flex justify-start gap-4 animate-pulse mb-6">
            <div className="w-10 h-10 rounded-lg border border-blue-500/30 bg-slate-900 flex items-center justify-center">
              <Icons.Bot />
            </div>
            <div className="bg-slate-900/80 border border-slate-800 rounded-2xl rounded-tl-none px-6 py-4 shadow-sm">
              <div className="flex gap-2">
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></span>
              </div>
            </div>
          </div>
        )}
        {chatState.error && (
          <div className="p-4 rounded-lg bg-red-950/20 border border-red-900 text-red-400 text-xs font-mono">
            {chatState.error}
          </div>
        )}
        <div ref={messagesEndRef} className="h-8" />
      </main>

      {/* Modals */}
      {showAuth && <AuthModal onSuccess={handleAuthSuccess} />}
      {showPlans && <PlanSelection 
        currentPlan={user?.plan || 'FREE'} 
        onUpgrade={handleUpgrade} 
        onClose={() => setShowPlans(false)} 
      />}

      {/* Bottom Interface */}
      <ChatInput 
        onSend={handleSendMessage} 
        disabled={chatState.isLoading} 
        placeholder={user ? "Analyze security vector..." : "Authenticate to begin operation..."}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  isLight?: boolean;
}

type AuthView = 'signin' | 'signup' | 'forgot' | 'reset-password';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, isLight }) => {
  const [view, setView] = useState<AuthView>('signin');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    // Simulate network delay
    await new Promise(r => setTimeout(r, 800));

    const users = JSON.parse(localStorage.getItem('cyber_users') || '[]');

    if (view === 'signup') {
      if (!formData.username || !formData.email || !formData.password) {
        setError('All fields are mandatory.');
      } else if (!formData.email.includes('@')) {
        setError('Invalid email format.');
      } else if (formData.password.length < 8) {
        setError('Password must be at least 8 characters.');
      } else if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match.');
      } else if (users.find((u: any) => u.email === formData.email)) {
        setError('User already exists in encrypted database.');
      } else {
        const newUser: User = {
          id: Math.random().toString(36).substr(2, 9),
          username: formData.username,
          email: formData.email,
          plan: 'FREE',
          createdDate: Date.now()
        };
        users.push({ ...newUser, password: formData.password });
        localStorage.setItem('cyber_users', JSON.stringify(users));
        // Auto-confirm logic
        onSuccess(newUser);
      }
    } else if (view === 'signin') {
      const user = users.find((u: any) => u.email === formData.email && u.password === formData.password);
      if (user) {
        onSuccess({
          id: user.id,
          username: user.username,
          email: user.email,
          plan: user.plan || 'FREE',
          createdDate: user.createdDate
        });
      } else {
        setError('Access Denied. Invalid credentials or node failure.');
      }
    } else if (view === 'forgot') {
      const exists = users.find((u: any) => u.email === formData.email);
      if (exists) {
        setView('reset-password');
      } else {
        setError('Node identity not found in database.');
      }
    } else if (view === 'reset-password') {
      if (formData.password.length < 8) {
        setError('New password must be at least 8 characters.');
      } else {
        const userIdx = users.findIndex((u: any) => u.email === formData.email);
        if (userIdx !== -1) {
          users[userIdx].password = formData.password;
          localStorage.setItem('cyber_users', JSON.stringify(users));
          setView('signin');
          setError('');
          alert('Credential override successful. Please sign in.');
        }
      }
    }
    setLoading(false);
  };

  const bgClass = isLight ? 'bg-white border-slate-200 shadow-slate-200' : 'bg-slate-900 border-emerald-500/30 shadow-emerald-500/10';
  const headerClass = isLight ? 'bg-slate-100 border-slate-200' : 'bg-emerald-500/10 border-emerald-500/20';
