              <Icons.Shield />
            </div>
          </div>
          <h2 className={`text-xl font-bold font-mono ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>
            {view === 'signin' && 'SECURE LOGIN'}
            {view === 'signup' && 'INITIALIZING NODE'}
            {view === 'forgot' && 'CREDENTIAL RECOVERY'}
            {view === 'reset-password' && 'OVERRIDE PASSWORD'}
          </h2>
          <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-widest">
            {loading ? 'Processing protocol...' : 'Verification required'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-4">
          {error && (
            <div className={`bg-red-500/10 border border-red-500/30 text-red-500 p-3 rounded-lg text-[11px] font-bold font-mono animate-pulse`}>
              [SYSTEM ERROR]: {error}
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Username</label>
              <input
                type="text"
                placeholder="Operative_01"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'forgot') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Email Address</label>
              <input
                type="email"
