                value={formData.email}
                onChange={e => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'reset-password') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>
                {view === 'reset-password' ? 'New Password' : 'Password'}
              </label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Confirm Password</label>
