import { User, PlanType } from '../types';

interface DBUser extends User {
  password_hash: string;
}

const STORAGE_KEY = 'defendra_db_users';

export const dbService = {
  getUsers: (): DBUser[] => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('Database read error', e);
      return [];
    }
  },

  saveUsers: (users: DBUser[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(users));
  },

  findUserByEmail: (email: string): DBUser | undefined => {
    const users = dbService.getUsers();
    return users.find(u => u.email.toLowerCase() === email.toLowerCase());
  },

  createUser: (username: string, email: string, passwordHash: string): User => {
    const users = dbService.getUsers();
    const newUser: DBUser = {
      id: Math.random().toString(36).substr(2, 9),
      username,
      email: email.toLowerCase(),
      password_hash: passwordHash,
      plan: 'FREE',
      createdDate: Date.now()
    };
    users.push(newUser);
    dbService.saveUsers(users);

    // Return the clean user object without password_hash
    const { password_hash, ...cleanUser } = newUser;
    return cleanUser;
  },

  updateUserPlan: (userId: string, plan: PlanType) => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.id === userId);
    if (index !== -1) {
      users[index].plan = plan;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  },

  updateUserPassword: (email: string, newPasswordHash: string) => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());
    if (index !== -1) {
      users[index].password_hash = newPasswordHash;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  }
};

