      }],
      isLoading: false,
      error: null
    });
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const handleUpgrade = (newPlan: PlanType) => {
    if (!user) return;
    const success = dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));

      setShowPlans(false);
      setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: Date.now().toString(),
            role: 'assistant',
            content: `[PLAN UPDATED]: Defendra protocol migrated to ${newPlan}. Your upgraded capabilities are now live.`,
            timestamp: Date.now(),
          }
        ]
      }));
    }
  };

  const handleSendMessage = async (content: string) => {
    if (!user) {
      setShowAuth(true);
      return;
    }

    if (user.plan === 'FREE' && chatState.messages.filter(m => m.role === 'user').length >= 5) {
       setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() },
          { id: (Date.now() + 1).toString(), role: 'assistant', content: "[WARNING]: FREE TIER LIMIT REACHED. Upgrade Defendra for expanded security analysis.", timestamp: Date.now() }
        ]
      }));
      return;
    }

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() };
    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true, error: null }));

    try {
      const assistantId = (Date.now() + 1).toString();
      setChatState(prev => ({ ...prev, messages: [...prev.messages, { id: assistantId, role: 'assistant', content: '', timestamp: Date.now() }] }));

      let fullResponse = "";
      for await (const chunk of gemini.streamMessage(content)) {
        fullResponse += chunk;
        setChatState(prev => {
          const newMessages = [...prev.messages];
          const idx = newMessages.findIndex(m => m.id === assistantId);
          if (idx !== -1) newMessages[idx] = { ...newMessages[idx], content: fullResponse };
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err) {
      setChatState(prev => ({ ...prev, error: "[ERROR]: Defendra node communication failure." }));
    } finally {
      setChatState(prev => ({ ...prev, isLoading: false }));
    }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto shadow-2xl border-x relative transition-colors duration-300 ${
      isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950/40 backdrop-blur-sm border-slate-900'
    }`}>

      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] transition-colors ${
        isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        Defendra Protocol Interface // Operative Session // Theme: {theme.toUpperCase()}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 transition-colors ${
        isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'
      }`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg transition-colors ${
            isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'
          }`}>
            <Icons.Shield />
          </div>
          <div>
            <h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${isLight ? 'bg-blue-500' : 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,1)]'}`}></span>
              <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest font-mono">Secure Node</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={toggleTheme}
            className={`p-2 rounded-lg border transition-all ${
              isLight ? 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-emerald-500/30'
            }`}
          >
            {isLight ? <Icons.Moon /> : <Icons.Sun />}
          </button>

          {user ? (
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPlans(true)}
                className={`hidden md:flex flex-col items-end px-3 py-1.5 rounded-lg border transition-all ${
                  isLight ? 'bg-slate-50 border-slate-200 hover:bg-slate-100' : 'bg-slate-950/50 border-slate-800 hover:border-emerald-500/30'
                }`}
              >
                <span className="text-[9px] text-slate-500 font-bold uppercase">Plan</span>
                <span className={`text-[11px] font-bold font-mono ${isLight ? 'text-blue-600' : 'text-emerald-400'}`}>{user.plan}</span>
              </button>

              <div className="flex flex-col items-end">
                <span className={`text-[10px] font-bold font-mono ${isLight ? 'text-slate-700' : 'text-slate-100'}`}>@{user.username}</span>
                <button onClick={handleSignOut} className="text-[9px] text-red-500 font-bold uppercase tracking-widest hover:underline">Exit</button>
              </div>
            </div>
          ) : (
            <button 
              onClick={() => setShowAuth(true)}
              className={`px-6 py-2 font-bold rounded-lg text-xs transition-all active:scale-95 shadow-lg ${
                isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-500 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
              }`}
            >
              INITIALIZE
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map((msg) => (
          <ChatMessage key={msg.id} message={msg} />
        ))}
        {chatState.isLoading && (
          <div className="flex justify-start gap-4 animate-pulse mb-6">
            <div className={`w-10 h-10 rounded-lg border flex items-center justify-center ${
              isLight ? 'bg-slate-100 border-slate-200' : 'bg-slate-900 border-blue-500/30'
            }`}>
              <Icons.Bot />
            </div>
            <div className={`rounded-2xl rounded-tl-none px-6 py-4 shadow-sm border ${
              isLight ? 'bg-white border-slate-200' : 'bg-slate-900/80 border-slate-800'
            }`}>
              <div className="flex gap-2">
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></span>
              </div>
            </div>
          </div>
        )}
        {chatState.error && (
          <div className="p-4 rounded-lg bg-red-500/10 border border-red-500/30 text-red-500 text-xs font-mono">
            {chatState.error}
          </div>
        )}
        <div ref={messagesEndRef} className="h-8" />
      </main>

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} />}

      <ChatInput 
        onSend={handleSendMessage} 
