import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../constants';

interface ChatInputProps {
  onSend: (message: string) => void;
  disabled: boolean;
  placeholder?: string;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSend, disabled, placeholder = "Input security query..." }) => {
  const [input, setInput] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'inherit';
      const scrollHeight = textareaRef.current.scrollHeight;
      textareaRef.current.style.height = `${Math.min(scrollHeight, 150)}px`;
    }
  }, [input]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !disabled) {
      onSend(input.trim());
      setInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div className="border-t border-slate-800 bg-slate-950/80 backdrop-blur-md p-4 pb-8 md:pb-4">
      <form onSubmit={handleSubmit} className="relative max-w-4xl mx-auto flex items-end gap-3">
        <div className="relative flex-1">
          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={disabled}
            className="w-full pl-4 pr-4 py-3.5 rounded-xl border border-slate-800 focus:outline-none focus:border-emerald-500/50 transition-all resize-none bg-slate-900/50 text-emerald-50 text-xs leading-relaxed scrollbar-hide font-mono shadow-inner"
            rows={1}
          />
        </div>
        <button
          type="submit"
          disabled={!input.trim() || disabled}
          className={`p-4 rounded-xl transition-all border ${
            input.trim() && !disabled 
              ? 'bg-emerald-500 text-slate-950 border-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.3)] active:scale-95' 
              : 'bg-slate-900 text-slate-600 border-slate-800 cursor-not-allowed opacity-50'
          }`}
        >
          <Icons.Send />
        </button>
      </form>
      <div className="mt-3 text-center flex items-center justify-center gap-6">
         <p className="text-[9px] text-slate-500 uppercase tracking-widest font-mono">
          System: <span className="text-emerald-500">Secure</span>
        </p>
        <p className="text-[9px] text-slate-500 uppercase tracking-widest font-mono">
          Model: <span className="text-blue-500">Defendra-v1.0</span>
        </p>
      </div>
    </div>
  );
};

