import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { dbService } from './services/dbService';
import { Icons, PLANS } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('defendra_theme') as 'dark' | 'light') || 'dark';
  });

  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem('defendra_session');
    return stored ? JSON.parse(stored) : null;
  });

  const [chatState, setChatState] = useState<ChatState>({
    messages: [
      {
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: INITIALIZING DEFENDRA AI PROTOCOL...\n\nGreetings, Operative. I am Defendra, your specialized cybersecurity node. I can provide guidance on digital safety, ethical security education, and data protection.\n\nPlease authenticate to proceed with full assistance.",
        timestamp: Date.now(),
      }
    ],
    isLoading: false,
    error: null,
  });

  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    localStorage.setItem('defendra_theme', theme);
    if (theme === 'light') {
      document.body.style.backgroundColor = '#f8fafc';
    } else {
      document.body.style.backgroundColor = '#020617';
    }
  }, [theme]);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [chatState.messages, scrollToBottom]);

  const handleAuthSuccess = (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);

    setChatState(prev => ({
      ...prev,
      messages: [
        ...prev.messages,
        {
          id: Date.now().toString(),
          role: 'assistant',
          content: `[AUTH SUCCESS]: Defendra access granted for @${authenticatedUser.username}.\nSTATUS: Online\nENCRYPTION: Active\n\nHow can I assist your operation?`,
          timestamp: Date.now(),
        }
      ]
    }));
  };

  const handleSignOut = () => {
    setUser(null);
    localStorage.removeItem('defendra_session');
    gemini.resetChat();
    stopAudio();
    setChatState({
      messages: [{
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: SESSION TERMINATED. Login required for Defendra assistance.",
        timestamp: Date.now(),
      }],
      isLoading: false,
      error: null
    });
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const stopAudio = () => {
    if (currentAudioSourceRef.current) {
      currentAudioSourceRef.current.stop();
      currentAudioSourceRef.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (messageId: string, text: string) => {
    if (speakingId === messageId) {
      stopAudio();
      return;
    }

    stopAudio();
    setSpeakingId(messageId);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      const base64Audio = await gemini.generateSpeech(text);

      if (base64Audio) {
        const audioData = gemini.decodeBase64(base64Audio);
        const buffer = await gemini.decodeAudioData(audioData, ctx);

        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => {
          if (speakingId === messageId) setSpeakingId(null);
        };

        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setSpeakingId(null);
      }
    } catch (err) {
      console.error("Speech playback error:", err);
      setSpeakingId(null);
    }
  };

  const handleUpgrade = (newPlan: PlanType) => {
    if (!user) return;
    const success = dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));

      setShowPlans(false);
      setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: Date.now().toString(),
            role: 'assistant',
            content: `[PLAN UPDATED]: Defendra protocol migrated to ${newPlan}. Your upgraded capabilities are now live.`,
            timestamp: Date.now(),
          }
        ]
      }));
    }
  };

  const handleSendMessage = async (content: string) => {
    if (!user) {
      setShowAuth(true);
      return;
    }

    if (user.plan === 'FREE' && chatState.messages.filter(m => m.role === 'user').length >= 5) {
       setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() },
          { id: (Date.now() + 1).toString(), role: 'assistant', content: "[WARNING]: FREE TIER LIMIT REACHED. Upgrade Defendra for expanded security analysis.", timestamp: Date.now() }
        ]
      }));
      return;
    }

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() };
    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true, error: null }));

    try {
      const assistantId = (Date.now() + 1).toString();
      setChatState(prev => ({ ...prev, messages: [...prev.messages, { id: assistantId, role: 'assistant', content: '', timestamp: Date.now() }] }));

      let fullResponse = "";
      for await (const chunk of gemini.streamMessage(content)) {
        fullResponse += chunk;
        setChatState(prev => {
          const newMessages = [...prev.messages];
          const idx = newMessages.findIndex(m => m.id === assistantId);
          if (idx !== -1) newMessages[idx] = { ...newMessages[idx], content: fullResponse };
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err) {
      setChatState(prev => ({ ...prev, error: "[ERROR]: Defendra node communication failure." }));
    } finally {
      setChatState(prev => ({ ...prev, isLoading: false }));
    }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto shadow-2xl border-x relative transition-colors duration-300 ${
      isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950/40 backdrop-blur-sm border-slate-900'
    }`}>

      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] transition-colors ${
        isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        Defendra Protocol Interface // Operative Session // Theme: {theme.toUpperCase()}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 transition-colors ${
        isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'
      }`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg transition-colors ${
            isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'
          }`}>
            <Icons.Shield />
          </div>
          <div>
            <h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${isLight ? 'bg-blue-500' : 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,1)]'}`}></span>
              <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest font-mono">Secure Node</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={toggleTheme}
            className={`p-2 rounded-lg border transition-all ${
              isLight ? 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-emerald-500/30'
            }`}
          >
            {isLight ? <Icons.Moon /> : <Icons.Sun />}
          </button>

          {user ? (
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPlans(true)}
                className={`hidden md:flex flex-col items-end px-3 py-1.5 rounded-lg border transition-all ${
                  isLight ? 'bg-slate-50 border-slate-200 hover:bg-slate-100' : 'bg-slate-950/50 border-slate-800 hover:border-emerald-500/30'
                }`}
              >
                <span className="text-[9px] text-slate-500 font-bold uppercase">Plan</span>
                <span className={`text-[11px] font-bold font-mono ${isLight ? 'text-blue-600' : 'text-emerald-400'}`}>{user.plan}</span>
              </button>

              <div className="flex flex-col items-end">
                <span className={`text-[10px] font-bold font-mono ${isLight ? 'text-slate-700' : 'text-slate-100'}`}>@{user.username}</span>
                <button onClick={handleSignOut} className="text-[9px] text-red-500 font-bold uppercase tracking-widest hover:underline">Exit</button>
              </div>
            </div>
          ) : (
            <button 
              onClick={() => setShowAuth(true)}
              className={`px-6 py-2 font-bold rounded-lg text-xs transition-all active:scale-95 shadow-lg ${
                isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-500 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
              }`}
            >
              INITIALIZE
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map((msg) => (
          <ChatMessage 
            key={msg.id} 
            message={msg} 
            onSpeak={(text) => handleSpeak(msg.id, text)}
            isSpeaking={speakingId === msg.id}
          />
        ))}
        {chatState.isLoading && (
          <div className="flex justify-start gap-4 animate-pulse mb-6">
            <div className={`w-10 h-10 rounded-lg border flex items-center justify-center ${
              isLight ? 'bg-slate-100 border-slate-200' : 'bg-slate-900 border-blue-500/30'
            }`}>
              <Icons.Bot />
            </div>
            <div className={`rounded-2xl rounded-tl-none px-6 py-4 shadow-sm border ${
              isLight ? 'bg-white border-slate-200' : 'bg-slate-900/80 border-slate-800'
            }`}>
              <div className="flex gap-2">
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></span>
              </div>
            </div>
          </div>
        )}
        {chatState.error && (
          <div className="p-4 rounded-lg bg-red-500/10 border border-red-500/30 text-red-500 text-xs font-mono">
            {chatState.error}
          </div>
        )}
        <div ref={messagesEndRef} className="h-8" />
      </main>

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} />}

      <ChatInput 
        onSend={handleSendMessage} 
        disabled={chatState.isLoading} 
        placeholder={user ? "Analyze security vector..." : "Defendra authentication required..."}
      />
    </div>
  );
};

export default App;

export type Role = 'user' | 'assistant';

export type PlanType = 'FREE' | 'BASIC' | 'PRO';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: number;
}

export interface User {
  id: string;
  username: string;
  email: string;
  plan: PlanType;
  createdDate: number;
  isEmailConfirmed: boolean;
}

export interface ChatState {
  messages: Message[];
  isLoading: boolean;
  error: string | null;
}

export interface AuthState {
  user: User | null;
  sessionToken: string | null;
}

import { User, PlanType } from '../types';

interface DBUser extends User {
  password_hash: string;
}

const STORAGE_KEY = 'defendra_db_users';

export const dbService = {
  getUsers: (): DBUser[] => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('Database read error', e);
      return [];
    }
  },

  saveUsers: (users: DBUser[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(users));
  },

  findUserByEmail: (email: string): DBUser | undefined => {
    const users = dbService.getUsers();
    return users.find(u => u.email.toLowerCase() === email.toLowerCase());
  },

  createUser: (username: string, email: string, passwordHash: string): User => {
    const users = dbService.getUsers();
    const newUser: DBUser = {
      id: Math.random().toString(36).substr(2, 9),
      username,
      email: email.toLowerCase(),
      password_hash: passwordHash,
      plan: 'FREE',
      createdDate: Date.now(),
      isEmailConfirmed: true // Auto-confirmed by default for testing
    };
    users.push(newUser);
    dbService.saveUsers(users);

    // Return the clean user object without password_hash
    const { password_hash, ...cleanUser } = newUser;
    return cleanUser;
  },

  updateUserPlan: (userId: string, plan: PlanType) => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.id === userId);
    if (index !== -1) {
      users[index].plan = plan;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  },

  updateUserPassword: (email: string, newPasswordHash: string) => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());
    if (index !== -1) {
      users[index].password_hash = newPasswordHash;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  }
};

import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  isLight?: boolean;
}

type AuthView = 'signin' | 'signup' | 'forgot' | 'reset-password';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, isLight }) => {
  const [view, setView] = useState<AuthView>('signin');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMsg('PROVISIONING NODE...');

    // Simulate network delay for that "hacking" feel
    await new Promise(r => setTimeout(r, 600));

    if (view === 'signup') {
      if (!formData.username || !formData.email || !formData.password) {
        setError('All credentials mandatory.');
      } else if (!formData.email.includes('@')) {
        setError('Invalid email format.');
      } else if (formData.password.length < 8) {
        setError('Password must be at least 8 characters.');
      } else if (formData.password !== formData.confirmPassword) {
        setError('Passwords mismatched.');
      } else if (dbService.findUserByEmail(formData.email)) {
        setError('Node identity already exists.');
      } else {
        setStatusMsg('BYPASSING VERIFICATION...');
        await new Promise(r => setTimeout(r, 400));
        setStatusMsg('EMAIL AUTO-CONFIRMED');
        await new Promise(r => setTimeout(r, 300));

        const newUser = dbService.createUser(formData.username, formData.email, formData.password);
        onSuccess(newUser);
      }
    } else if (view === 'signin') {
      const user = dbService.findUserByEmail(formData.email);
      if (user && (user as any).password_hash === formData.password) {
        const { password_hash, ...cleanUser } = user as any;
        onSuccess(cleanUser);
      } else {
        setError('Access Denied. Identity mismatched.');
      }
    } else if (view === 'forgot') {
      const exists = dbService.findUserByEmail(formData.email);
      if (exists) {
        setView('reset-password');
      } else {
        setError('Identity not found in node database.');
      }
    } else if (view === 'reset-password') {
      if (formData.password.length < 8) {
        setError('New password must be at least 8 characters.');
      } else {
        const success = dbService.updateUserPassword(formData.email, formData.password);
        if (success) {
          setView('signin');
          setError('');
          alert('Credential override confirmed. Proceed to login.');
        }
      }
    }
    setLoading(false);
    setStatusMsg('');
  };

  const bgClass = isLight ? 'bg-white border-slate-200 shadow-slate-200' : 'bg-slate-900 border-emerald-500/30 shadow-emerald-500/10';
  const headerClass = isLight ? 'bg-slate-100 border-slate-200' : 'bg-emerald-500/10 border-emerald-500/20';
  const inputClass = isLight ? 'bg-slate-50 border-slate-300 text-slate-900' : 'bg-slate-950 border-slate-800 text-emerald-50';
  const labelClass = isLight ? 'text-slate-500' : 'text-slate-500';

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className={`${bgClass} border w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200`}>
        <div className={`${headerClass} p-6 border-b text-center`}>
          <div className="flex justify-center mb-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${isLight ? 'bg-blue-600 text-white' : 'bg-emerald-500 text-slate-900'}`}>
              <Icons.Shield />
            </div>
          </div>
          <h2 className={`text-xl font-bold font-mono ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>
            {view === 'signin' && 'DEFENDRA LOGIN'}
            {view === 'signup' && 'PROVISION NODE'}
            {view === 'forgot' && 'CREDENTIAL SEARCH'}
            {view === 'reset-password' && 'OVERRIDE KEYS'}
          </h2>
          <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-widest font-mono">
            {loading ? statusMsg : 'Identity Verification Required'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-4">
          {error && (
            <div className={`bg-red-500/10 border border-red-500/30 text-red-500 p-3 rounded-lg text-[11px] font-bold font-mono animate-pulse`}>
              [SYSTEM ERROR]: {error}
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Username</label>
              <input
                type="text"
                placeholder="Agent_Name"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'forgot') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Email Address</label>
              <input
                type="email"
                placeholder="op@defendra.secure"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all font-mono ${inputClass}`}
                value={formData.email}
                onChange={e => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'reset-password') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>
                {view === 'reset-password' ? 'New Password' : 'Password'}
              </label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Confirm Password</label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.confirmPassword}
                onChange={e => setFormData({ ...formData, confirmPassword: e.target.value })}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full font-bold py-3 rounded-lg transition-all shadow-lg active:scale-95 text-sm tracking-widest ${
              loading 
              ? 'opacity-50 cursor-not-allowed bg-slate-400' 
              : isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-600 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
            }`}
          >
            {loading ? 'EXECUTING...' : (
              view === 'signin' ? 'AUTHENTICATE' : 
              view === 'signup' ? 'REGISTER NODE' : 
              view === 'forgot' ? 'SEARCH' : 'CONFIRM OVERRIDE'
            )}
          </button>

          <div className="flex flex-col gap-2 pt-2">
            {view === 'signin' && (
              <button
                type="button"
                onClick={() => setView('forgot')}
                className="text-[10px] text-slate-400 hover:text-emerald-500 uppercase tracking-tighter"
              >
                Lost Identity? [RECOVER]
              </button>
            )}
            <button
              type="button"
              onClick={() => {
                setView(view === 'signin' ? 'signup' : 'signin');
                setError('');
              }}
              className="text-[10px] text-slate-400 hover:text-emerald-500 uppercase tracking-tighter"
            >
              {view === 'signin' ? 'New Operative? Provision Node' : 'Existing Node? Authenticate'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AuthModal;

import { User, PlanType } from '../types';

interface DBUser extends User {
  password_hash: string;
}

const STORAGE_KEY = 'defendra_db_vault';

export const dbService = {
  /**
   * Initializes the DB if it doesn't exist.
   */
  init: () => {
    if (!localStorage.getItem(STORAGE_KEY)) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify([]));
    }
  },

  /**
   * Retrieves all users from the persistent vault.
   */
  getUsers: (): DBUser[] => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('[DATABASE ERROR]: Could not parse vault data.', e);
      return [];
    }
  },

  /**
   * Commit changes to the persistent vault.
   */
  saveUsers: (users: DBUser[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(users));
  },

  /**
   * Searches for an operative by email identity.
   */
  findUserByEmail: (email: string): DBUser | undefined => {
    const users = dbService.getUsers();
    return users.find(u => u.email.toLowerCase() === email.toLowerCase());
  },

  /**
   * Registers a new operative node in the vault.
   */
  createUser: (username: string, email: string, passwordHash: string): User => {
    const users = dbService.getUsers();
    const newUser: DBUser = {
      id: `NODE-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      username,
      email: email.toLowerCase(),
      password_hash: passwordHash,
      plan: 'FREE',
      createdDate: Date.now(),
      isEmailConfirmed: true // Auto-confirmed as per system requirement
    };
    users.push(newUser);
    dbService.saveUsers(users);

    // Return sanitized profile (exclude credentials)
    const { password_hash, ...sanitized } = newUser;
    return sanitized;
  },

  /**
   * Upgrades an operative's plan level in the vault.
   */
  updateUserPlan: (userId: string, plan: PlanType): boolean => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.id === userId);
    if (index !== -1) {
      users[index].plan = plan;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  },

  /**
   * Overrides stored credentials for recovery purposes.
   */
  updateUserPassword: (email: string, newPasswordHash: string): boolean => {
    const users = dbService.getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());
    if (index !== -1) {
      users[index].password_hash = newPasswordHash;
      dbService.saveUsers(users);
      return true;
    }
    return false;
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
