import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { dbService } from './services/dbService';
import { Icons, PLANS } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';

const App: React.FC = () => {
  // Initialize Database on Mount
  useEffect(() => {
    dbService.init();
  }, []);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('defendra_theme') as 'dark' | 'light') || 'dark';
  });

  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem('defendra_session');
    if (stored) {
      const sessionUser = JSON.parse(stored);
      // Verify session with DB to ensure plan and existence are synced
      const dbRecord = dbService.findUserByEmail(sessionUser.email);
      if (dbRecord) {
        const { password_hash, ...clean } = dbRecord;
        return clean;
      }
    }
    return null;
  });

  const [chatState, setChatState] = useState<ChatState>({
    messages: [
      {
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: INITIALIZING DEFENDRA AI PROTOCOL...\n\nGreetings, Operative. I am Defendra, your specialized cybersecurity node. I can provide guidance on digital safety, ethical security education, and data protection.\n\nPlease authenticate to proceed with full assistance.",
        timestamp: Date.now(),
      }
    ],
    isLoading: false,
    error: null,
  });

  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const [audioLoadingId, setAudioLoadingId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    localStorage.setItem('defendra_theme', theme);
    document.body.style.backgroundColor = theme === 'light' ? '#f8fafc' : '#020617';
  }, [theme]);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [chatState.messages, scrollToBottom]);

  const handleAuthSuccess = (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);

    setChatState(prev => ({
      ...prev,
      messages: [
        ...prev.messages,
        {
          id: `AUTH-${Date.now()}`,
          role: 'assistant',
          content: `[AUTH SUCCESS]: Node identification confirmed for @${authenticatedUser.username}.\nPLAN LEVEL: ${authenticatedUser.plan}\nDATABASE: CONNECTED\n\nHow can I assist your operation today?`,
          timestamp: Date.now(),
        }
      ]
    }));
  };

  const handleSignOut = () => {
    setUser(null);
    localStorage.removeItem('defendra_session');
    gemini.resetChat();
    stopAudio();
    setChatState({
      messages: [{
        id: '1',
        role: 'assistant',
        content: "[SYSTEM]: SESSION TERMINATED. User node disconnected from vault.",
        timestamp: Date.now(),
      }],
      isLoading: false,
      error: null
    });
  };

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  const stopAudio = () => {
    if (currentAudioSourceRef.current) {
      try {
        currentAudioSourceRef.current.stop();
      } catch (e) {
        // Source might already be stopped
      }
      currentAudioSourceRef.current = null;
    }
    setSpeakingId(null);
    setAudioLoadingId(null);
  };

  const handleSpeak = async (messageId: string, text: string) => {
    if (speakingId === messageId || audioLoadingId === messageId) {
      stopAudio();
      return;
    }

    stopAudio();
    setAudioLoadingId(messageId);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const ctx = audioContextRef.current;

      // Resume context if suspended (browser policy)
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      const base64Audio = await gemini.generateSpeech(text);
      setAudioLoadingId(null);

      if (base64Audio) {
        setSpeakingId(messageId);
        const audioData = gemini.decodeBase64(base64Audio);
        const buffer = await gemini.decodeAudioData(audioData, ctx);

        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);

        source.onended = () => {
          setSpeakingId(prev => prev === messageId ? null : prev);
        };

        currentAudioSourceRef.current = source;
        source.start(0);
      }
    } catch (err) {
      console.error("Speech playback error:", err);
      setAudioLoadingId(null);
      setSpeakingId(null);
    }
  };

  const handleUpgrade = (newPlan: PlanType) => {
    if (!user) return;
    const success = dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: `PLAN-${Date.now()}`,
            role: 'assistant',
            content: `[VAULT UPDATE]: Subscription status elevated to ${newPlan}. Your operative clearances have been updated in the master database.`,
            timestamp: Date.now(),
          }
        ]
      }));
    }
  };

  const handleSendMessage = async (content: string) => {
    if (!user) { setShowAuth(true); return; }

    const userMsgCount = chatState.messages.filter(m => m.role === 'user').length;
    if (user.plan === 'FREE' && userMsgCount >= 5) {
       setChatState(prev => ({
        ...prev,
        messages: [
          ...prev.messages,
          { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() },
          { id: (Date.now() + 1).toString(), role: 'assistant', content: "[DATABASE WARNING]: Free tier query quota exceeded. Please upgrade your node plan to continue deep analysis.", timestamp: Date.now() }
        ]
      }));
      return;
    }

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content, timestamp: Date.now() };
    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true, error: null }));

    try {
      const assistantId = (Date.now() + 1).toString();
      setChatState(prev => ({ ...prev, messages: [...prev.messages, { id: assistantId, role: 'assistant', content: '', timestamp: Date.now() }] }));

      let fullResponse = "";
      for await (const chunk of gemini.streamMessage(content)) {
        fullResponse += chunk;
        setChatState(prev => {
          const newMessages = [...prev.messages];
          const idx = newMessages.findIndex(m => m.id === assistantId);
          if (idx !== -1) newMessages[idx] = { ...newMessages[idx], content: fullResponse };
          return { ...prev, messages: newMessages };
        });
      }
    } catch (err) {
      setChatState(prev => ({ ...prev, error: "[DATABASE ERROR]: Communication with Defendra Vault timed out." }));
    } finally {
      setChatState(prev => ({ ...prev, isLoading: false }));
    }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto shadow-2xl border-x relative transition-colors duration-300 ${
      isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950/40 backdrop-blur-sm border-slate-900'
    }`}>

      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] transition-colors flex items-center justify-center gap-4 ${
        isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        <span>Defendra Node Interface</span>
        <span className="opacity-40">|</span>
        <span className="flex items-center gap-1">
          <span className={`w-1 h-1 rounded-full animate-pulse ${isLight ? 'bg-blue-600' : 'bg-slate-900'}`}></span>
          DB STATUS: STABLE
        </span>
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 transition-colors ${
        isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'
      }`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg transition-colors ${
            isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'
          }`}>
            <Icons.Shield />
          </div>
          <div>
            <h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className={`w-1.5 h-1.5 rounded-full animate-pulse ${isLight ? 'bg-blue-500' : 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,1)]'}`}></span>
              <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest font-mono">Secure Node</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={toggleTheme}
            className={`p-2 rounded-lg border transition-all ${
              isLight ? 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-emerald-500/30'
            }`}
            title="Toggle theme mode"
          >
            {isLight ? <Icons.Moon /> : <Icons.Sun />}
          </button>

          {user ? (
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPlans(true)}
                className={`hidden md:flex flex-col items-end px-3 py-1.5 rounded-lg border transition-all ${
                  isLight ? 'bg-slate-50 border-slate-200 hover:bg-slate-100' : 'bg-slate-950/50 border-slate-800 hover:border-emerald-500/30'
                }`}
              >
                <span className="text-[9px] text-slate-500 font-bold uppercase">Plan</span>
                <span className={`text-[11px] font-bold font-mono ${isLight ? 'text-blue-600' : 'text-emerald-400'}`}>{user.plan}</span>
              </button>

              <div className="flex flex-col items-end">
                <span className={`text-[10px] font-bold font-mono ${isLight ? 'text-slate-700' : 'text-slate-100'}`}>@{user.username}</span>
                <button onClick={handleSignOut} className="text-[9px] text-red-500 font-bold uppercase tracking-widest hover:underline">Disconnect</button>
              </div>
            </div>
          ) : (
            <button 
              onClick={() => setShowAuth(true)}
              className={`px-6 py-2 font-bold rounded-lg text-xs transition-all active:scale-95 shadow-lg ${
                isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-500 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
              }`}
            >
              INITIALIZE
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map((msg) => (
          <ChatMessage 
            key={msg.id} 
            message={msg} 
            onSpeak={(text) => handleSpeak(msg.id, text)}
            isSpeaking={speakingId === msg.id}
            isLoadingAudio={audioLoadingId === msg.id}
            isLight={isLight}
          />
        ))}
        {chatState.isLoading && (
          <div className="flex justify-start gap-4 animate-pulse mb-6">
            <div className={`w-10 h-10 rounded-lg border flex items-center justify-center ${
              isLight ? 'bg-slate-100 border-slate-200' : 'bg-slate-900 border-blue-500/30'
            }`}>
              <Icons.Bot />
            </div>
            <div className={`rounded-2xl rounded-tl-none px-6 py-4 shadow-sm border ${
              isLight ? 'bg-white border-slate-200' : 'bg-slate-900/80 border-slate-800'
            }`}>
              <div className="flex gap-2">
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></span>
                <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></span>
              </div>
            </div>
          </div>
        )}
        {chatState.error && (
          <div className="p-4 rounded-lg bg-red-500/10 border border-red-500/30 text-red-500 text-xs font-mono">
            {chatState.error}
          </div>
        )}
        <div ref={messagesEndRef} className="h-8" />
      </main>

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} isLight={isLight} />}

      <ChatInput 
        onSend={handleSendMessage} 
        disabled={chatState.isLoading} 
        placeholder={user ? "Analyze security vector..." : "Vault access required..."}
        isLight={isLight}
      />
    </div>
  );
};

