import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  isLight?: boolean;
}

type AuthView = 'signin' | 'signup' | 'forgot' | 'verification-challenge' | 'reset-password';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, isLight }) => {
  const [view, setView] = useState<AuthView>('signin');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    otp: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (view === 'signup') {
      setStatusMsg('PROVISIONING NODE...');
      await new Promise(r => setTimeout(r, 600));
      if (!formData.username || !formData.email || !formData.password) {
        setError('All credentials mandatory.');
      } else if (!formData.email.includes('@')) {
        setError('Invalid email format.');
      } else if (formData.password.length < 8) {
        setError('Password must be at least 8 characters.');
      } else if (formData.password !== formData.confirmPassword) {
        setError('Passwords mismatched.');
      } else if (dbService.findUserByEmail(formData.email)) {
        setError('Node identity already exists.');
      } else {
        setStatusMsg('BYPASSING VERIFICATION...');
        await new Promise(r => setTimeout(r, 400));
        setStatusMsg('EMAIL AUTO-CONFIRMED');
        await new Promise(r => setTimeout(r, 300));

        const newUser = dbService.createUser(formData.username, formData.email, formData.password);
        onSuccess(newUser);
      }
    } else if (view === 'signin') {
      setStatusMsg('AUTHENTICATING...');
      await new Promise(r => setTimeout(r, 600));
      const user = dbService.findUserByEmail(formData.email);
      if (user && (user as any).password_hash === formData.password) {
        const { password_hash, ...cleanUser } = user as any;
        onSuccess(cleanUser);
      } else {
        setError('Access Denied. Identity mismatched.');
      }
    } else if (view === 'forgot') {
      setStatusMsg('QUERYING VAULT...');
      await new Promise(r => setTimeout(r, 800));
      const exists = dbService.findUserByEmail(formData.email);
      if (exists) {
        setStatusMsg('IDENTITY FOUND. ISSUING CHALLENGE...');
        await new Promise(r => setTimeout(r, 600));
        setView('verification-challenge');
      } else {
        setError('Identity not found in node database.');
      }
    } else if (view === 'verification-challenge') {
      setStatusMsg('VERIFYING CHALLENGE CODE...');
      await new Promise(r => setTimeout(r, 700));
      if (formData.otp.length === 6) {
        setStatusMsg('CHALLENGE BYPASSED. GRANTED OVERRIDE.');
        await new Promise(r => setTimeout(r, 500));
        setView('reset-password');
      } else {
        setError('Invalid access code format (6 digits required).');
      }
    } else if (view === 'reset-password') {
      setStatusMsg('OVERRIDING CREDENTIALS...');
      await new Promise(r => setTimeout(r, 900));
      if (formData.password.length < 8) {
        setError('New password must be at least 8 characters.');
      } else {
        const success = dbService.updateUserPassword(formData.email, formData.password);
        if (success) {
          setStatusMsg('SUCCESS: OVERRIDE COMPLETE.');
          await new Promise(r => setTimeout(r, 500));
          setView('signin');
          setError('');
          setFormData({ ...formData, password: '', confirmPassword: '', otp: '' });
        }
      }
    }
    setLoading(false);
    setStatusMsg('');
  };

  const bgClass = isLight ? 'bg-white border-slate-200 shadow-slate-200' : 'bg-slate-900 border-emerald-500/30 shadow-emerald-500/10';
  const headerClass = isLight ? 'bg-slate-100 border-slate-200' : 'bg-emerald-500/10 border-emerald-500/20';
  const inputClass = isLight ? 'bg-slate-50 border-slate-300 text-slate-900' : 'bg-slate-950 border-slate-800 text-emerald-50';
  const labelClass = isLight ? 'text-slate-500 font-mono' : 'text-slate-500 font-mono';

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className={`${bgClass} border w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200`}>
        <div className={`${headerClass} p-6 border-b text-center`}>
          <div className="flex justify-center mb-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${isLight ? 'bg-blue-600 text-white shadow-lg' : 'bg-emerald-500 text-slate-900 shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}>
              <Icons.Shield />
            </div>
          </div>
          <h2 className={`text-xl font-bold font-mono tracking-tighter ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>
            {view === 'signin' && 'DEFENDRA LOGIN'}
            {view === 'signup' && 'PROVISION NODE'}
            {view === 'forgot' && 'SEARCH VAULT'}
            {view === 'verification-challenge' && 'VERIFY CHALLENGE'}
            {view === 'reset-password' && 'OVERRIDE KEYS'}
          </h2>
          <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-widest font-mono">
            {loading ? statusMsg : 'Access Authorization Required'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-4">
          {error && (
            <div className={`bg-red-500/10 border border-red-500/30 text-red-500 p-3 rounded-lg text-[11px] font-bold font-mono animate-pulse`}>
              [SYSTEM ERROR]: {error}
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Username</label>
              <input
                type="text"
                placeholder="Agent_Name"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'forgot') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Email Address</label>
              <input
                type="email"
                placeholder="op@defendra.secure"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all font-mono ${inputClass}`}
                value={formData.email}
                disabled={view === 'verification-challenge' || view === 'reset-password'}
                onChange={e => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          )}

          {view === 'verification-challenge' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Access Code (6-Digits)</label>
              <input
                type="text"
                maxLength={6}
                placeholder="000000"
                className={`w-full border rounded-lg px-4 py-2.5 text-lg text-center tracking-[0.5em] focus:border-emerald-500/50 focus:outline-none transition-all font-mono ${inputClass}`}
                value={formData.otp}
                onChange={e => setFormData({ ...formData, otp: e.target.value.replace(/\D/g, '') })}
              />
              <p className="text-[9px] text-slate-500 mt-2 font-mono uppercase tracking-tighter">Enter any 6 digits for testing verification bypass.</p>
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'reset-password') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>
                {view === 'reset-password' ? 'New Security Key' : 'Security Key'}
              </label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Verify Key</label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.confirmPassword}
                onChange={e => setFormData({ ...formData, confirmPassword: e.target.value })}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full font-bold py-3 rounded-lg transition-all shadow-lg active:scale-95 text-sm tracking-widest font-mono ${
              loading 
              ? 'opacity-50 cursor-not-allowed bg-slate-400' 
              : isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-600 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
            }`}
          >
            {loading ? 'EXECUTING...' : (
              view === 'signin' ? 'AUTHENTICATE' : 
              view === 'signup' ? 'REGISTER NODE' : 
              view === 'forgot' ? 'QUERY VAULT' : 
              view === 'verification-challenge' ? 'SUBMIT CODE' : 'CONFIRM OVERRIDE'
            )}
          </button>

          <div className="flex flex-col gap-2 pt-2 items-center">
            {view === 'signin' && (
              <button
                type="button"
                onClick={() => setView('forgot')}
                className="text-[10px] text-slate-500 hover:text-emerald-500 uppercase tracking-widest font-mono transition-colors"
              >
                [ Lost Identity? ]
              </button>
            )}
            <button
              type="button"
              onClick={() => {
                setView(view === 'signin' ? 'signup' : 'signin');
                setError('');
              }}
              className="text-[10px] text-slate-500 hover:text-emerald-500 uppercase tracking-widest font-mono transition-colors"
            >
              {view === 'signin' ? 'Provision New Node' : 'Authenticate Existing Node'}
            </button>
            {(view === 'forgot' || view === 'verification-challenge' || view === 'reset-password') && (
              <button
                type="button"
                onClick={() => setView('signin')}
                className="text-[10px] text-red-500/70 hover:text-red-500 uppercase tracking-widest font-mono transition-colors mt-1"
              >
                [ Abort Operation ]
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

