            className={`px-3 py-1.5 rounded-lg border text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 transition-all ${
              mode === m.id 
                ? isLight ? 'bg-blue-600 text-white border-blue-600' : 'bg-emerald-500 text-slate-950 border-emerald-500 shadow-lg'
                : isLight ? 'bg-slate-50 border-slate-200 text-slate-500' : 'bg-slate-900 border-slate-800 text-slate-400'
            }`}
          >
            {m.icon} {m.label}
          </button>
        ))}
        <button
          onClick={onLiveToggle}
          className={`px-3 py-1.5 rounded-lg border text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 transition-all ${
            isLight ? 'bg-red-50 text-red-600 border-red-200' : 'bg-red-500/10 text-red-400 border-red-500/20'
          }`}
        >
          <Icons.Mic /> LIVE
        </button>
      </div>

      <form onSubmit={handleSubmit} className="relative max-w-4xl mx-auto flex items-end gap-3">
        <div className="relative flex-1">
          {selectedFile && (
            <div className="absolute -top-12 left-0 right-0 flex items-center gap-2 p-2 bg-slate-900/90 rounded-t-lg border border-slate-800">
              <span className="text-[10px] text-emerald-500 font-mono truncate max-w-[200px]">{selectedFile.name}</span>
              <button onClick={() => setSelectedFile(null)} className="text-red-500 text-xs">×</button>
            </div>
          )}
          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={mode === 'image' ? "Describe image to generate..." : placeholder}
            disabled={disabled}
            className={`w-full pl-4 pr-12 py-3.5 rounded-xl border focus:outline-none transition-all resize-none text-xs leading-relaxed scrollbar-hide font-mono shadow-inner ${
              isLight ? "bg-slate-50 border-slate-200 text-slate-800 focus:border-blue-500" : "bg-slate-900/50 border-slate-800 text-emerald-50 focus:border-emerald-500/50"
            }`}
            rows={1}
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="absolute right-3 bottom-3 p-1 opacity-50 hover:opacity-100 transition-opacity"
          >
            <Icons.Lock />
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} hidden accept="image/*,video/*" />
        </div>

        {mode === 'image' && (
          <select 
            value={imageSize} 
            onChange={(e) => setImageSize(e.target.value as any)}
            className={`p-3.5 rounded-xl border text-[10px] font-bold ${
              isLight ? 'bg-white border-slate-200' : 'bg-slate-900 border-slate-800 text-emerald-400'
            }`}
          >
            <option value="1K">1K</option>
            <option value="2K">2K</option>
            <option value="4K">4K</option>
          </select>
        )}

        <button
          type="submit"
