            )}
            {(view !== 'signin' && view !== 'signup') && (
              <button
                type="button"
                onClick={() => {
                  setView('signin');
                  setError('');
                  setPendingUser(null);
                }}
                className="text-[10px] text-red-500/70 hover:text-red-500 uppercase tracking-widest font-mono transition-colors mt-1"
              >
                [ Abort Operation ]
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

