  useEffect(() => { scrollToBottom(); }, [chatState.messages, scrollToBottom]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const stopAllAudio = () => {
    if (currentSourceRef.current) {
      currentSourceRef.current.stop();
      currentSourceRef.current = null;
    }
    setSpeakingMsgId(null);
  };

  const handleSpeak = async (message: Message) => {
    // If already speaking this message, stop it
    if (speakingMsgId === message.id) {
      stopAllAudio();
      return;
    }

    // Stop any other speaking message
    stopAllAudio();
    setLoadingAudioMsgId(message.id);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await gemini.generateSpeech(message.content);

      if (!base64Audio) {
        throw new Error("Failed to generate speech buffer.");
      }

      const audioData = gemini.decodeBase64(base64Audio);
      const audioBuffer = await gemini.decodeAudioData(audioData, audioContextRef.current);

      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);

      source.onended = () => {
        if (speakingMsgId === message.id) {
          setSpeakingMsgId(null);
        }
      };

      setLoadingAudioMsgId(null);
      setSpeakingMsgId(message.id);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Speech error:", err);
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(null);
    }
  };

  const handleAuthSuccess = async (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);

    const history = await dbService.getChatHistory(authenticatedUser.id);
    if (history.length > 0) {
      setChatState(prev => ({ ...prev, messages: history }));
    } else {
      setChatState({
        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[AUTH SUCCESS]: Node identification confirmed for @${authenticatedUser.username}.\n\nWelcome back, Operative. Vault logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
    }

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: Image generated at ${imageSize} resolution.`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo generation complete. Finalizing media buffers...`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit applied successfully.`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze this media file.", base64, file.type);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps');
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content);
      } else if (mode === 'lite') {
        let full = "";
        for await (const chunk of gemini.streamMessageLite(content)) { full += chunk; }
        responseContent = full;
      } else {
        let full = "";
        for await (const chunk of gemini.streamMessage(content)) { full += chunk; }
        responseContent = full;
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[WARNING]: Guest cycle limit reached. Further interactions require Node Authentication.";
        }
      }

      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, assistantMsg],
        isLoading: false
      }));

      if (user) {
        await dbService.saveMessage(user.id, assistantMsg);
      }

    } catch (err: any) {
      setChatState(prev => ({ ...prev, error: `[SYSTEM ERROR]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[VAULT UPDATE]: Subscription status elevated to ${newPlan}. Clearance verified.`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }

    if (isLive) {
      liveSessionRef.current?.close();
      setIsLive(false);
      return;
    }

    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;

      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });

      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto border-x relative transition-colors duration-300 ${isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950 border-slate-900'}`}>
      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-colors ${
        !user 
          ? 'bg-amber-500 text-slate-950' 
          : isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        <span>{user ? `Defendra Node v2.5 [@${user.username}]` : `GUEST_ACCESS_NODE [${3 - guestMessageCount}/3_CYCLES_REMAINING]`}</span>
        {isLive && <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></span> LIVE</span>}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 ${isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'}`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg ${isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'}`}>
            <Icons.Shield />
          </div>
          <div><h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1></div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} className="p-2 transition-transform active:scale-90">{isLight ? <Icons.Moon /> : <Icons.Sun />}</button>
          {user && <button onClick={() => setShowProfile(true)} className="p-2 hover:text-emerald-400 transition-colors"><Icons.User /></button>}
          {!user && (
            <button 
              onClick={() => setShowAuth(true)} 
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all active:scale-95 ${
                guestMessageCount >= 3 
                  ? 'bg-amber-500 text-slate-950 animate-pulse shadow-lg shadow-amber-500/20' 
                  : 'bg-emerald-500 text-slate-950'
              }`}
            >
              {guestMessageCount >= 3 ? 'AUTHENTICATE_REQUIRED' : 'INITIALIZE'}
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map(m => (
          <ChatMessage 
            key={m.id} 
            message={m} 
            isLight={isLight} 
            onSpeak={() => handleSpeak(m)}
            isSpeaking={speakingMsgId === m.id}
            isLoadingAudio={loadingAudioMsgId === m.id}
          />
        ))}
        {chatState.isLoading && <div className="text-[10px] font-mono animate-pulse text-emerald-500">PROCCESSING_QUERY...</div>}
        <div ref={messagesEndRef} />
      </main>

      <ChatInput 
        onSend={handleSendMessage} 
        onLiveToggle={handleLiveToggle} 
        disabled={chatState.isLoading} 
        isLight={isLight} 
        placeholder={!user ? `Guest cycle ${guestMessageCount + 1} of 3...` : "Input security query..."}
      />

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} isLight={isLight} />}
      {showProfile && user && <UserProfile user={user} onClose={() => setShowProfile(false)} onManageSubscription={() => { setShowProfile(false); setShowPlans(true); }} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} isLight={isLight} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  onGuestChoice: () => void;
  isLight?: boolean;
}

type AuthView = 'choice' | 'signin' | 'signup' | 'forgot' | 'verification-challenge' | 'reset-password' | 'email-verification';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, onGuestChoice, isLight }) => {
  const [view, setView] = useState<AuthView>('choice');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    otp: ''
  });
  const [pendingUser, setPendingUser] = useState<User | null>(null);
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (view === 'signup') {
        setStatusMsg('PROVISIONING NODE...');
        if (!formData.username || !formData.email || !formData.password) {
          setError('All credentials mandatory.');
        } else if (!formData.email.includes('@')) {
          setError('Invalid email format.');
        } else if (formData.password.length < 8) {
          setError('Password must be at least 8 characters.');
        } else if (formData.password !== formData.confirmPassword) {
          setError('Passwords mismatched.');
        } else if (await dbService.findUserByEmail(formData.email)) {
          setError('Node identity already exists.');
        } else {
          const newUser = await dbService.createUser(formData.username, formData.email, formData.password);
          setPendingUser(newUser);
          setStatusMsg('ENCRYPTING VERIFICATION TOKEN...');
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          setGeneratedOtp(code);
          setStatusMsg(`CHALLENGE ISSUED. [SIMULATION]: CODE IS ${code}`);
          await new Promise(r => setTimeout(r, 1500));
          setView('email-verification');
        }
      } else if (view === 'signin') {
        setStatusMsg('AUTHENTICATING...');
        const user = await dbService.findUserByEmail(formData.email);

        if (user && (user as any).password_hash === formData.password) {
          if (!user.isEmailConfirmed) {
            setPendingUser(user);
            const code = Math.floor(100000 + Math.random() * 900000).toString();
            setGeneratedOtp(code);
            setStatusMsg(`CHALLENGE RE-SENT. [SIMULATION]: CODE IS ${code}`);
            await new Promise(r => setTimeout(r, 1500));
            setView('email-verification');
          } else {
            const { password_hash, ...cleanUser } = user as any;
            await dbService.recordLogin(cleanUser.id);
            onSuccess(cleanUser);
          }
        } else {
          setError('Access Denied. Identity mismatched.');
        }
      } else if (view === 'email-verification') {
        setStatusMsg('CONFIRMING IDENTITY...');
        if (formData.otp === generatedOtp && pendingUser) {
          await dbService.confirmEmail(pendingUser.id);
          setStatusMsg('IDENTITY VERIFIED. ACCESS GRANTED.');
          await new Promise(r => setTimeout(r, 500));
          onSuccess({ ...pendingUser, isEmailConfirmed: true });
        } else {
          setError('Verification code mismatch. Try again.');
        }
      } else if (view === 'forgot') {
        setStatusMsg('QUERYING VAULT...');
        const exists = await dbService.findUserByEmail(formData.email);
        if (exists) {
          setStatusMsg('IDENTITY FOUND. DISPATCHING CHALLENGE...');
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          setGeneratedOtp(code);
          setStatusMsg(`CHALLENGE SENT. [SIMULATION]: CODE IS ${code}`);
          await new Promise(r => setTimeout(r, 2000));
          setView('verification-challenge');
        } else {
          setError('Identity not found in node database.');
        }
      } else if (view === 'verification-challenge') {
        setStatusMsg('VERIFYING CHALLENGE CODE...');
        if (formData.otp === generatedOtp) {
          setStatusMsg('CHALLENGE BYPASSED. GRANTED OVERRIDE.');
          await new Promise(r => setTimeout(r, 500));
          setView('reset-password');
          setFormData({ ...formData, password: '', confirmPassword: '' });
        } else {
          setError('Invalid access code. Authorization failed.');
        }
      } else if (view === 'reset-password') {
        setStatusMsg('OVERRIDING CREDENTIALS...');
        if (formData.password.length < 8) {
          setError('New password must be at least 8 characters.');
        } else {
          const success = await dbService.updateUserPassword(formData.email, formData.password);
          if (success) {
            setStatusMsg('SUCCESS: OVERRIDE COMPLETE.');
            await new Promise(r => setTimeout(r, 1000));
            setView('signin');
            setError('');
            setFormData({ ...formData, password: '', confirmPassword: '', otp: '' });
          } else {
            setError('Vault commit failed. Try again.');
          }
        }
      }
    } catch (err) {
      setError('System malfunction. Protocol aborted.');
    } finally {
      setLoading(false);
      setStatusMsg('');
    }
  };

  const bgClass = isLight ? 'bg-white border-slate-200 shadow-slate-200' : 'bg-slate-900 border-emerald-500/30 shadow-emerald-500/10';
  const headerClass = isLight ? 'bg-slate-100 border-slate-200' : 'bg-emerald-500/10 border-emerald-500/20';
  const inputClass = isLight ? 'bg-slate-50 border-slate-300 text-slate-900 placeholder-slate-400' : 'bg-slate-950 border-slate-800 text-emerald-50 placeholder-slate-700';
  const labelClass = isLight ? 'text-slate-500 font-mono' : 'text-slate-500 font-mono';

  if (view === 'choice') {
    return (
      <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4">
        <div className={`${bgClass} border w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200`}>
          <div className={`${headerClass} p-10 border-b text-center`}>
            <div className="flex justify-center mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center rotate-45 ${isLight ? 'bg-blue-600 text-white shadow-xl' : 'bg-emerald-500 text-slate-950 shadow-[0_0_20px_rgba(16,185,129,0.5)]'}`}>
                <div className="-rotate-45 scale-150">
                  <Icons.Shield />
                </div>
              </div>
            </div>
            <h2 className={`text-2xl font-bold font-mono tracking-tighter uppercase ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>
              INITIALIZE_NODE_PROTOCOL
            </h2>
            <p className="text-[10px] text-slate-500 mt-2 uppercase tracking-[0.3em] font-mono">
              Identity identification required for encrypted session buffer.
            </p>
          </div>

          <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Agent Option */}
            <button
              onClick={() => setView('signin')}
              className={`flex flex-col items-center text-center p-6 rounded-xl border transition-all group ${
                isLight 
                ? 'bg-slate-50 border-slate-200 hover:border-blue-500 hover:bg-blue-50' 
                : 'bg-slate-950 border-slate-800 hover:border-emerald-500/50 hover:bg-emerald-500/5'
              }`}
            >
              <div className={`mb-4 p-3 rounded-full transition-colors ${isLight ? 'bg-blue-100 text-blue-600 group-hover:bg-blue-600 group-hover:text-white' : 'bg-emerald-500/10 text-emerald-500 group-hover:bg-emerald-500 group-hover:text-slate-950'}`}>
                <Icons.User />
              </div>
              <h3 className={`font-mono font-bold text-sm mb-2 ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>AGENT_LOGIN</h3>
              <p className="text-[9px] text-slate-500 leading-relaxed uppercase tracking-wider">
                Full session persistence. Persistent audit logs. Access to advanced neural tools.
              </p>
            </button>

            {/* Guest Option */}
            <button
              onClick={onGuestChoice}
              className={`flex flex-col items-center text-center p-6 rounded-xl border transition-all group ${
                isLight 
                ? 'bg-slate-50 border-slate-200 hover:border-slate-400 hover:bg-slate-100' 
                : 'bg-slate-950 border-slate-800 hover:border-slate-500 hover:bg-slate-900'
              }`}
            >
              <div className={`mb-4 p-3 rounded-full transition-colors ${isLight ? 'bg-slate-200 text-slate-600 group-hover:bg-slate-800 group-hover:text-white' : 'bg-slate-800 text-slate-400 group-hover:bg-slate-100 group-hover:text-slate-950'}`}>
                <Icons.Zap />
              </div>
              <h3 className={`font-mono font-bold text-sm mb-2 ${isLight ? 'text-slate-200' : 'text-slate-100'}`}>EPHEMERAL_GUEST</h3>
              <p className="text-[9px] text-slate-500 leading-relaxed uppercase tracking-wider">
                3 query cycles limit. No persistence. Automated buffer purge on session termination.
              </p>
            </button>
          </div>

          <div className={`p-4 text-center border-t text-[8px] font-mono tracking-widest ${isLight ? 'bg-slate-50 border-slate-200 text-slate-400' : 'bg-slate-950 border-slate-800 text-slate-600'}`}>
            SECURE_ENCRYPTION_STANDARDS_APPLIED_BY_DEFENDRA_VAULT_v2.5
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className={`${bgClass} border w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200`}>
        <div className={`${headerClass} p-6 border-b text-center relative`}>
          <button 
            onClick={() => setView('choice')}
            className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500 hover:text-emerald-400 transition-colors"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" className="w-5 h-5">
              <path d="M19 12H5M12 19l-7-7 7-7" />
            </svg>
          </button>

          <div className="flex justify-center mb-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${isLight ? 'bg-blue-600 text-white shadow-lg' : 'bg-emerald-500 text-slate-950 shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}>
              <Icons.Shield />
            </div>
          </div>
          <h2 className={`text-xl font-bold font-mono tracking-tighter uppercase ${isLight ? 'text-slate-900' : 'text-emerald-400'}`}>
            {view === 'signin' && 'DEFENDRA LOGIN'}
            {view === 'signup' && 'PROVISION NODE'}
            {view === 'forgot' && 'SEARCH VAULT'}
            {view === 'verification-challenge' && 'VERIFY CHALLENGE'}
            {view === 'email-verification' && 'CONFIRM IDENTITY'}
            {view === 'reset-password' && 'OVERRIDE KEYS'}
          </h2>
          <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-widest font-mono h-4">
            {loading ? statusMsg : 'Access Authorization Required'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-4">
          {error && (
            <div className={`bg-red-500/10 border border-red-500/30 text-red-500 p-3 rounded-lg text-[11px] font-bold font-mono animate-pulse`}>
              [SYSTEM ERROR]: {error}
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Username</label>
              <input
                type="text"
                placeholder="Agent_Name"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'forgot') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Email Address</label>
              <input
                type="email"
                placeholder="op@defendra.secure"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all font-mono ${inputClass}`}
                value={formData.email}
                disabled={loading}
                onChange={e => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          )}

          {(view === 'verification-challenge' || view === 'email-verification') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Challenge Code</label>
              <input
                type="text"
                maxLength={6}
                placeholder="000000"
                className={`w-full border rounded-lg px-4 py-3 text-2xl text-center tracking-[0.5em] focus:border-emerald-500/50 focus:outline-none transition-all font-mono ${inputClass}`}
                value={formData.otp}
                onChange={e => setFormData({ ...formData, otp: e.target.value.replace(/\D/g, '') })}
              />
              <p className="text-[9px] text-slate-500 mt-3 font-mono uppercase tracking-tighter text-center">
                {view === 'email-verification' 
                  ? 'Identify confirmation code required to unlock node access.' 
                  : 'Check encrypted buffer for code verification.'}
              </p>
            </div>
          )}

          {(view === 'signin' || view === 'signup' || view === 'reset-password') && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>
                {view === 'reset-password' ? 'New Security Key' : 'Security Key'}
              </label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className={`block text-[10px] font-bold uppercase mb-1 tracking-wider ${labelClass}`}>Verify Key</label>
              <input
                type="password"
                placeholder="••••••••"
                className={`w-full border rounded-lg px-4 py-2.5 text-sm focus:border-emerald-500/50 focus:outline-none transition-all ${inputClass}`}
                value={formData.confirmPassword}
                onChange={e => setFormData({ ...formData, confirmPassword: e.target.value })}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full font-bold py-3 rounded-lg transition-all shadow-lg active:scale-95 text-sm tracking-widest font-mono ${
              loading 
              ? 'opacity-50 cursor-not-allowed bg-slate-400' 
              : isLight ? 'bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-700' : 'bg-emerald-600 text-slate-950 shadow-emerald-500/20 hover:bg-emerald-400'
            }`}
          >
            {loading ? 'EXECUTING...' : (
              view === 'signin' ? 'AUTHENTICATE' : 
              view === 'signup' ? 'REGISTER NODE' : 
              view === 'forgot' ? 'QUERY VAULT' : 
              view === 'email-verification' ? 'VERIFY IDENTITY' :
              view === 'verification-challenge' ? 'VERIFY CODE' : 'CONFIRM OVERRIDE'
            )}
          </button>

          <div className="flex flex-col gap-2 pt-2 items-center">
            {view === 'signin' && (
              <button
                type="button"
                onClick={() => setView('forgot')}
                className="text-[10px] text-slate-500 hover:text-emerald-500 uppercase tracking-widest font-mono transition-colors"
              >
                [ Lost Identity? ]
              </button>
            )}
            {(view === 'signin' || view === 'signup') && (
              <button
                type="button"
                onClick={() => {
                  setView(view === 'signin' ? 'signup' : 'signin');
                  setError('');
                  setGeneratedOtp('');
                }}
                className="text-[10px] text-slate-500 hover:text-emerald-500 uppercase tracking-widest font-mono transition-colors"
              >
                {view === 'signin' ? 'Provision New Node' : 'Authenticate Existing Node'}
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default AuthModal;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { dbService } from './services/dbService';
import { Icons } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput, { InputMode } from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';
import UserProfile from './components/UserProfile';
import { LiveServerMessage } from '@google/genai';

const App: React.FC = () => {
  useEffect(() => { dbService.init(); }, []);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => (localStorage.getItem('defendra_theme') as any) || 'dark');
  const [user, setUser] = useState<User | null>(null);
  const [guestMessageCount, setGuestMessageCount] = useState<number>(0);
  const [chatState, setChatState] = useState<ChatState>({
    messages: [{ 
      id: '1', 
      role: 'assistant', 
      content: "[SYSTEM]: INITIALIZING DEFENDRA NODE GATEWAY...\n\nPlease select an access protocol to proceed with the secure session buffer.", 
      timestamp: Date.now() 
    }],
    isLoading: false,
    error: null,
  });

  const [isLive, setIsLive] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  // Audio State
  const [speakingMsgId, setSpeakingMsgId] = useState<string | null>(null);
  const [loadingAudioMsgId, setLoadingAudioMsgId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Restore Session and Logs
  useEffect(() => {
    const restoreSession = async () => {
      const stored = localStorage.getItem('defendra_session');
      if (stored) {
        const sessionData = JSON.parse(stored);
        const dbRecord = await dbService.findUserByEmail(sessionData.email);
        if (dbRecord) {
          const { password_hash, ...clean } = dbRecord;
          setUser(clean);
          const history = await dbService.getChatHistory(clean.id);
          if (history.length > 0) {
            setChatState(prev => ({ ...prev, messages: history }));
          }
        } else {
          setShowAuth(true); // No user record, show selector
        }
      } else {
        setShowAuth(true); // No session, show selector
      }
    };
    restoreSession();
  }, []);

  useEffect(() => {
    localStorage.setItem('defendra_theme', theme);
    document.body.style.backgroundColor = theme === 'light' ? '#f8fafc' : '#020617';
  }, [theme]);

  const scrollToBottom = useCallback(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), []);
  useEffect(() => { scrollToBottom(); }, [chatState.messages, scrollToBottom]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const stopAllAudio = () => {
    if (currentSourceRef.current) {
      currentSourceRef.current.stop();
      currentSourceRef.current = null;
    }
    setSpeakingMsgId(null);
  };

  const handleSpeak = async (message: Message) => {
    if (speakingMsgId === message.id) {
      stopAllAudio();
      return;
    }
    stopAllAudio();
    setLoadingAudioMsgId(message.id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const base64Audio = await gemini.generateSpeech(message.content);
      if (!base64Audio) throw new Error("Failed to generate speech buffer.");
      const audioData = gemini.decodeBase64(base64Audio);
      const audioBuffer = await gemini.decodeAudioData(audioData, audioContextRef.current);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => { if (speakingMsgId === message.id) setSpeakingMsgId(null); };
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(message.id);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(null);
    }
  };

  const handleAuthSuccess = async (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);
    setGuestMessageCount(0); // Reset guest counter if they log in

    const history = await dbService.getChatHistory(authenticatedUser.id);
    if (history.length > 0) {
      setChatState(prev => ({ ...prev, messages: history }));
    } else {
      setChatState({
        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[AUTH SUCCESS]: Node identification confirmed for @${authenticatedUser.username}.\n\nWelcome back, Operative. Vault logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleGuestChoice = () => {
    setShowAuth(false);
    setUser(null);
    setGuestMessageCount(0);
    setChatState({
      messages: [{ 
        id: '1', 
        role: 'assistant', 
        content: "[GUEST_BYPASS]: Ephemeral access protocol initiated. Session will terminate after 3 query cycles.", 
        timestamp: Date.now() 
      }],
      isLoading: false,
      error: null,
    });
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
    }

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: Image generated at ${imageSize} resolution.`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo generation complete. Finalizing media buffers...`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit applied successfully.`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze this media file.", base64, file.type);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps');
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content);
      } else if (mode === 'lite') {
        let full = "";
        for await (const chunk of gemini.streamMessageLite(content)) { full += chunk; }
        responseContent = full;
      } else {
        let full = "";
        for await (const chunk of gemini.streamMessage(content)) { full += chunk; }
        responseContent = full;
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[WARNING]: Guest cycle limit reached. Further interactions require Node Authentication.";
        }
      }

      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, assistantMsg],
        isLoading: false
      }));

      if (user) {
        await dbService.saveMessage(user.id, assistantMsg);
      }

    } catch (err: any) {
      setChatState(prev => ({ ...prev, error: `[SYSTEM ERROR]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[VAULT UPDATE]: Subscription status elevated to ${newPlan}. Clearance verified.`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }
    if (isLive) { liveSessionRef.current?.close(); setIsLive(false); return; }
    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;
      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto border-x relative transition-colors duration-300 ${isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950 border-slate-900'}`}>
      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-colors ${
        !user 
          ? 'bg-amber-500 text-slate-950' 
          : isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        <span>{user ? `Defendra Node v2.5 [@${user.username}]` : `GUEST_ACCESS_NODE [${3 - guestMessageCount}/3_CYCLES_REMAINING]`}</span>
        {isLive && <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></span> LIVE</span>}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 ${isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'}`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg ${isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'}`}>
            <Icons.Shield />
          </div>
          <div><h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1></div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} className="p-2 transition-transform active:scale-90">{isLight ? <Icons.Moon /> : <Icons.Sun />}</button>
          {user && <button onClick={() => setShowProfile(true)} className="p-2 hover:text-emerald-400 transition-colors"><Icons.User /></button>}
          {!user && (
            <button 
              onClick={() => setShowAuth(true)} 
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all active:scale-95 ${
                guestMessageCount >= 3 
                  ? 'bg-amber-500 text-slate-950 animate-pulse shadow-lg shadow-amber-500/20' 
                  : 'bg-emerald-500 text-slate-950'
              }`}
            >
              {guestMessageCount >= 3 ? 'AUTHENTICATE_REQUIRED' : 'INITIALIZE'}
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map(m => (
          <ChatMessage 
            key={m.id} 
            message={m} 
            isLight={isLight} 
            onSpeak={() => handleSpeak(m)}
            isSpeaking={speakingMsgId === m.id}
            isLoadingAudio={loadingAudioMsgId === m.id}
          />
        ))}
        {chatState.isLoading && <div className="text-[10px] font-mono animate-pulse text-emerald-500">PROCCESSING_QUERY...</div>}
        <div ref={messagesEndRef} />
      </main>

      <ChatInput 
        onSend={handleSendMessage} 
        onLiveToggle={handleLiveToggle} 
        disabled={chatState.isLoading} 
        isLight={isLight} 
        placeholder={!user ? `Guest cycle ${guestMessageCount + 1} of 3...` : "Input security query..."}
      />

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} onGuestChoice={handleGuestChoice} isLight={isLight} />}
      {showProfile && user && <UserProfile user={user} onClose={() => setShowProfile(false)} onManageSubscription={() => { setShowProfile(false); setShowPlans(true); }} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} isLight={isLight} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  onGuestChoice: () => void;
  isLight?: boolean;
}

type AuthView = 'choice' | 'signin' | 'signup' | 'forgot' | 'verification-challenge' | 'reset-password' | 'email-verification';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, onGuestChoice, isLight }) => {
  const [view, setView] = useState<AuthView>('choice');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    otp: ''
  });
  const [pendingUser, setPendingUser] = useState<User | null>(null);
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const generateAndSetOtp = () => {
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(code);
    return code;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (view === 'signup') {
        setStatusMsg('PROVISIONING NODE...');
        if (!formData.username || !formData.email || !formData.password) {
          setError('All credentials mandatory.');
        } else if (!formData.email.includes('@')) {
          setError('Invalid email format.');
        } else if (formData.password.length < 8) {
          setError('Password must be at least 8 characters.');
        } else if (formData.password !== formData.confirmPassword) {
          setError('Passwords mismatched.');
        } else if (await dbService.findUserByEmail(formData.email)) {
          setError('Node identity already exists.');
        } else {
          const newUser = await dbService.createUser(formData.username, formData.email, formData.password);
          setPendingUser(newUser);
          setStatusMsg('ENCRYPTING VERIFICATION TOKEN...');
          const code = generateAndSetOtp();
          await new Promise(r => setTimeout(r, 1500));
          setView('email-verification');
        }
      } else if (view === 'signin') {
        setStatusMsg('AUTHENTICATING...');
        const user = await dbService.findUserByEmail(formData.email);

        if (user && (user as any).password_hash === formData.password) {
          if (!user.isEmailConfirmed) {
            setPendingUser(user);
            generateAndSetOtp();
            setStatusMsg(`CHALLENGE RE-SENT...`);
            await new Promise(r => setTimeout(r, 1500));
            setView('email-verification');
          } else {
            const { password_hash, ...cleanUser } = user as any;
            await dbService.recordLogin(cleanUser.id);
            onSuccess(cleanUser);
          }
        } else {
          setError('Access Denied. Identity mismatched.');
        }
      } else if (view === 'email-verification') {
        setStatusMsg('CONFIRMING IDENTITY...');
        if (formData.otp === generatedOtp && pendingUser) {
          await dbService.confirmEmail(pendingUser.id);
          setStatusMsg('IDENTITY VERIFIED. ACCESS GRANTED.');
          await new Promise(r => setTimeout(r, 500));
          onSuccess({ ...pendingUser, isEmailConfirmed: true });
        } else {
          setError('Verification code mismatch. Try again.');
        }
      } else if (view === 'forgot') {
        setStatusMsg('QUERYING VAULT...');
        const exists = await dbService.findUserByEmail(formData.email);
        if (exists) {
          setStatusMsg('IDENTITY FOUND. DISPATCHING CHALLENGE...');
          generateAndSetOtp();
          await new Promise(r => setTimeout(r, 2000));
          setView('verification-challenge');
        } else {
          setError('Identity not found in node database.');
        }
      } else if (view === 'verification-challenge') {
        setStatusMsg('VERIFYING CHALLENGE CODE...');
        if (formData.otp === generatedOtp) {
          setStatusMsg('CHALLENGE BYPASSED. GRANTED OVERRIDE.');
          await new Promise(r => setTimeout(r, 500));
          setView('reset-password');
          setFormData({ ...formData, password: '', confirmPassword: '' });
        } else {
          setError('Invalid access code. Authorization failed.');
        }
      } else if (view === 'reset-password') {
        setStatusMsg('OVERRIDING CREDENTIALS...');
        if (formData.password.length < 8) {
          setError('New password must be at least 8 characters.');
        } else {
          const success = await dbService.updateUserPassword(formData.email, formData.password);
          if (success) {
            setStatusMsg('SUCCESS: OVERRIDE COMPLETE.');
            await new Promise(r => setTimeout(r, 1000));
            setView('signin');
            setError('');
            setFormData({ ...formData, password: '', confirmPassword: '', otp: '' });
          } else {
            setError('Vault commit failed. Try again.');
          }
        }
      }
    } catch (err) {
      setError('System malfunction. Protocol aborted.');
    } finally {
      setLoading(false);
      setStatusMsg('');
    }
  };

