import { GoogleGenAI, Chat, GenerateContentResponse, Modality, Type, LiveServerMessage } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

export class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    // Default session uses gemini-3-flash-preview for the best balance of speed and accuracy
    this.chatSession = this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: '',
        config: { systemInstruction: SYSTEM_INSTRUCTION }
    }) as any;
  }

  // Ultra-Fast Chat using Flash Lite
  async *streamMessageLite(message: string): AsyncGenerator<string> {
    const chat = this.ai.chats.create({
      model: 'gemini-2.5-flash-lite-latest',
      config: { systemInstruction: SYSTEM_INSTRUCTION },
    });
    const result = await chat.sendMessageStream({ message });
    for await (const chunk of result) {
      const text = (chunk as GenerateContentResponse).text;
      if (text) yield text;
    }
  }

  // High-Speed Accurate Chat using Gemini 3 Flash
  // This replaces Pro-preview for general tasks to ensure "Fast and Accurate" performance
  async *streamMessage(message: string): AsyncGenerator<string> {
    const chat = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: { systemInstruction: SYSTEM_INSTRUCTION },
    });
    const result = await chat.sendMessageStream({ message });
    for await (const chunk of result) {
      const text = (chunk as GenerateContentResponse).text;
      if (text) yield text;
    }
  }

  // Grounded Search / Maps
  async generateGroundedContent(message: string, tool: 'googleSearch' | 'googleMaps'): Promise<{ text: string; links: any[] }> {
    const config: any = { tools: [] };
    if (tool === 'googleSearch') config.tools.push({ googleSearch: {} });
    if (tool === 'googleMaps') {
      config.tools.push({ googleMaps: {} });
    }

    const response = await this.ai.models.generateContent({
      model: tool === 'googleMaps' ? 'gemini-2.5-flash' : 'gemini-3-flash-preview',
      contents: message,
      config,
    });

    return {
      text: response.text || '',
      links: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  }

  // Deep Reasoning with Thinking (Higher Latency, Maximum Accuracy)
  async generateWithThinking(prompt: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 24576 } // Slightly lower budget for better speed
      },
    });
    return response.text || '';
  }

  // Image Generation
  async generateImage(prompt: string, size: '1K' | '2K' | '4K'): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: { aspectRatio: "1:1", imageSize: size }
      },
    });
    for (const part of response.candidates?.[0].content.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("No image generated");
  }

  // Image Editing
  async editImage(prompt: string, base64Image: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
          { text: prompt }
        ]
      },
    });
    for (const part of response.candidates?.[0].content.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Edit failed");
  }

  // Video Generation
  async generateVideo(prompt: string, imageBase64?: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      image: imageBase64 ? {
        imageBytes: imageBase64.split(',')[1],
        mimeType: 'image/png'
      } : undefined,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  // Media Analysis
  async analyzeMedia(prompt: string, base64Data: string, mimeType: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Faster analysis
      contents: {
        parts: [
          { inlineData: { data: base64Data.split(',')[1], mimeType } },
          { text: prompt }
        ]
      },
    });
    return response.text || '';
  }

  // Live API Connection
  connectLive(callbacks: any) {
    return this.ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks,
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
        },
      }
    });
  }

  // Speech generation
  async generateSpeech(text: string): Promise<string | undefined> {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say this naturally and concisely: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    } catch (e) { return undefined; }
  }

  decodeBase64(base64: string): Uint8Array {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  encodeBase64(bytes: Uint8Array): string {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  async decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number = 24000, numChannels: number = 1): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  }
}

