const App: React.FC = () => {
  useEffect(() => { dbService.init(); }, []);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => (localStorage.getItem('defendra_theme') as any) || 'dark');
  const [user, setUser] = useState<User | null>(null);
  const [guestMessageCount, setGuestMessageCount] = useState<number>(0);
  const [chatState, setChatState] = useState<ChatState>({
    messages: [{ 
      id: '1', 
      role: 'assistant', 
      content: "[SYSTEM]: INITIALIZING DEFENDRA NODE GATEWAY...\n\nPlease select an access protocol to proceed with the secure session buffer.", 
      timestamp: Date.now() 
    }],
    isLoading: false,
    error: null,
  });

  const [isLive, setIsLive] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  // Audio State
  const [speakingMsgId, setSpeakingMsgId] = useState<string | null>(null);
  const [loadingAudioMsgId, setLoadingAudioMsgId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Restore Session and Logs
  useEffect(() => {
    const restoreSession = async () => {
      const stored = localStorage.getItem('defendra_session');
      if (stored) {
        const sessionData = JSON.parse(stored);
        const dbRecord = await dbService.findUserByEmail(sessionData.email);
        if (dbRecord) {
          const { password_hash, ...clean } = dbRecord;
          setUser(clean);
          const history = await dbService.getChatHistory(clean.id);
          if (history.length > 0) {
            setChatState(prev => ({ ...prev, messages: history }));
          }
        } else {
          setShowAuth(true);
        }
      } else {
        setShowAuth(true);
      }
    };
    restoreSession();
  }, []);

  useEffect(() => {
    localStorage.setItem('defendra_theme', theme);
    document.body.style.backgroundColor = theme === 'light' ? '#f8fafc' : '#020617';
  }, [theme]);

  const scrollToBottom = useCallback(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), []);
  useEffect(() => { scrollToBottom(); }, [chatState.messages, scrollToBottom]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const stopAllAudio = () => {
    if (currentSourceRef.current) {
      currentSourceRef.current.stop();
      currentSourceRef.current = null;
    }
    setSpeakingMsgId(null);
  };

  const handleSpeak = async (message: Message) => {
    if (speakingMsgId === message.id) {
      stopAllAudio();
      return;
    }
    stopAllAudio();
    setLoadingAudioMsgId(message.id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const base64Audio = await gemini.generateSpeech(message.content);
      if (!base64Audio) throw new Error("Failed to generate speech buffer.");
      const audioData = gemini.decodeBase64(base64Audio);
      const audioBuffer = await gemini.decodeAudioData(audioData, audioContextRef.current);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => { if (speakingMsgId === message.id) setSpeakingMsgId(null); };
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(message.id);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(null);
    }
  };

  const handleAuthSuccess = async (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);
    setGuestMessageCount(0);

    const history = await dbService.getChatHistory(authenticatedUser.id);
    if (history.length > 0) {
      setChatState(prev => ({ ...prev, messages: history }));
    } else {
      setChatState({
        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[AUTH SUCCESS]: Node identification confirmed for @${authenticatedUser.username}.\n\nWelcome back, Operative. Vault logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleGuestChoice = () => {
    setShowAuth(false);
    setUser(null);
    setGuestMessageCount(0);
    setChatState({
      messages: [{ 
        id: '1', 
        role: 'assistant', 
        content: "[GUEST_BYPASS]: Ephemeral access protocol initiated. Session will terminate after 3 query cycles.", 
        timestamp: Date.now() 
      }],
      isLoading: false,
      error: null,
    });
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
    }

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      // Initial Placeholder for Streaming
      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: "",
        timestamp: Date.now()
      };

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: Image generated at ${imageSize} resolution.`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo generation complete. Finalizing media buffers...`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit applied successfully.`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze this media file.", base64, file.type);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps');
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content);
      } else {
        // TRUE STREAMING LOGIC
        setChatState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isLoading: false }));

        const stream = mode === 'lite' ? gemini.streamMessageLite(content) : gemini.streamMessage(content);

        for await (const chunk of stream) {
          responseContent += chunk;
          setChatState(prev => {
            const last = prev.messages[prev.messages.length - 1];
            if (last.id === assistantId) {
              const updatedMsg = { ...last, content: responseContent };
              return { ...prev, messages: [...prev.messages.slice(0, -1), updatedMsg] };
            }
            return prev;
          });
        }
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[WARNING]: Guest cycle limit reached. Further interactions require Node Authentication.";
        }
      }

      const finalAssistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      // If we weren't streaming (media modes), add the final message now
      if (mode !== 'lite' && mode !== 'default') {
        setChatState(prev => ({
          ...prev,
          messages: [...prev.messages, finalAssistantMsg],
          isLoading: false
        }));
      } else {
        // Update the streamed message with final data (grounding etc)
        setChatState(prev => {
           const idx = prev.messages.findIndex(m => m.id === assistantId);
           if (idx !== -1) {
             const newMessages = [...prev.messages];
             newMessages[idx] = finalAssistantMsg;
             return { ...prev, messages: newMessages, isLoading: false };
           }
           return { ...prev, isLoading: false };
        });
      }

      if (user) {
        await dbService.saveMessage(user.id, finalAssistantMsg);
      }

    } catch (err: any) {
      setChatState(prev => ({ ...prev, error: `[SYSTEM ERROR]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[VAULT UPDATE]: Subscription status elevated to ${newPlan}. Clearance verified.`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }
    if (isLive) { liveSessionRef.current?.close(); setIsLive(false); return; }
    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;
      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto border-x relative transition-colors duration-300 ${isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950 border-slate-900'}`}>
      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-colors ${
        !user 
          ? 'bg-amber-500 text-slate-950' 
          : isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        <span>{user ? `Defendra Node v2.5 [@${user.username}]` : `GUEST_ACCESS_NODE [${3 - guestMessageCount}/3_CYCLES_REMAINING]`}</span>
        {isLive && <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></span> LIVE</span>}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 ${isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'}`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg ${isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'}`}>
            <Icons.Shield />
          </div>
          <div><h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1></div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} className="p-2 transition-transform active:scale-90">{isLight ? <Icons.Moon /> : <Icons.Sun />}</button>
          {user && <button onClick={() => setShowProfile(true)} className="p-2 hover:text-emerald-400 transition-colors"><Icons.User /></button>}
          {!user && (
            <button 
              onClick={() => setShowAuth(true)} 
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all active:scale-95 ${
                guestMessageCount >= 3 
                  ? 'bg-amber-500 text-slate-950 animate-pulse shadow-lg shadow-amber-500/20' 
                  : 'bg-emerald-500 text-slate-950'
              }`}
            >
              {guestMessageCount >= 3 ? 'AUTHENTICATE_REQUIRED' : 'INITIALIZE'}
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map(m => (
          <ChatMessage 
            key={m.id} 
            message={m} 
            isLight={isLight} 
            onSpeak={() => handleSpeak(m)}
            isSpeaking={speakingMsgId === m.id}
            isLoadingAudio={loadingAudioMsgId === m.id}
          />
        ))}
        {chatState.isLoading && <div className="text-[10px] font-mono animate-pulse text-emerald-500">PROCCESSING_QUERY...</div>}
        <div ref={messagesEndRef} />
      </main>

      <ChatInput 
        onSend={handleSendMessage} 
        onLiveToggle={handleLiveToggle} 
        disabled={chatState.isLoading} 
        isLight={isLight} 
        placeholder={!user ? `Guest cycle ${guestMessageCount + 1} of 3...` : "Input security query..."}
      />

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} onGuestChoice={handleGuestChoice} isLight={isLight} />}
      {showProfile && user && <UserProfile user={user} onClose={() => setShowProfile(false)} onManageSubscription={() => { setShowProfile(false); setShowPlans(true); }} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} isLight={isLight} />}
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, GenerateContentResponse, Modality, Type, LiveServerMessage } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { PlanType } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private wrapPrompt(message: string, plan: PlanType): string {
    return `[USER_PLAN: ${plan}] ${message}`;
  }

  async *streamMessageLite(message: string, plan: PlanType): AsyncGenerator<string> {
    const chat = this.ai.chats.create({
      model: 'gemini-2.5-flash-lite-latest',
      config: { systemInstruction: SYSTEM_INSTRUCTION },
    });
    const result = await chat.sendMessageStream({ message: this.wrapPrompt(message, plan) });
    for await (const chunk of result) {
      const text = (chunk as GenerateContentResponse).text;
      if (text) yield text;
    }
  }

  async *streamMessage(message: string, plan: PlanType): AsyncGenerator<string> {
    const chat = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: { systemInstruction: SYSTEM_INSTRUCTION },
    });
    const result = await chat.sendMessageStream({ message: this.wrapPrompt(message, plan) });
    for await (const chunk of result) {
      const text = (chunk as GenerateContentResponse).text;
      if (text) yield text;
    }
  }

  async generateGroundedContent(message: string, tool: 'googleSearch' | 'googleMaps', plan: PlanType): Promise<{ text: string; links: any[] }> {
    const config: any = { 
      tools: [],
      systemInstruction: SYSTEM_INSTRUCTION 
    };
    if (tool === 'googleSearch') config.tools.push({ googleSearch: {} });
    if (tool === 'googleMaps') config.tools.push({ googleMaps: {} });

    const response = await this.ai.models.generateContent({
      model: tool === 'googleMaps' ? 'gemini-2.5-flash' : 'gemini-3-flash-preview',
      contents: this.wrapPrompt(message, plan),
      config,
    });

    return {
      text: response.text || '',
      links: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  }

  async generateWithThinking(prompt: string, plan: PlanType): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: this.wrapPrompt(prompt, plan),
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 24576 }
      },
    });
    return response.text || '';
  }

  async generateImage(prompt: string, size: '1K' | '2K' | '4K'): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: { aspectRatio: "1:1", imageSize: size }
      },
    });
    for (const part of response.candidates?.[0].content.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("No image generated");
  }

  async editImage(prompt: string, base64Image: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
          { text: prompt }
        ]
      },
    });
    for (const part of response.candidates?.[0].content.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Edit failed");
  }

  async generateVideo(prompt: string, imageBase64?: string): Promise<string> {
    let operation = await this.ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      image: imageBase64 ? {
        imageBytes: imageBase64.split(',')[1],
        mimeType: 'image/png'
      } : undefined,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await this.ai.operations.getVideosOperation({ operation: operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async analyzeMedia(prompt: string, base64Data: string, mimeType: string, plan: PlanType): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data.split(',')[1], mimeType } },
          { text: this.wrapPrompt(prompt, plan) }
        ]
      },
      config: { systemInstruction: SYSTEM_INSTRUCTION }
    });
    return response.text || '';
  }

  connectLive(callbacks: any) {
    return this.ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks,
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
        },
        systemInstruction: SYSTEM_INSTRUCTION
      }
    });
  }

  async generateSpeech(text: string): Promise<string | undefined> {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say this naturally and concisely: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    } catch (e) { return undefined; }
  }

  decodeBase64(base64: string): Uint8Array {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  }

  encodeBase64(bytes: Uint8Array): string {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  async decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number = 24000, numChannels: number = 1): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  }
}

export const gemini = new GeminiService();

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { dbService } from './services/dbService';
import { Icons } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput, { InputMode } from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';
import UserProfile from './components/UserProfile';
import { LiveServerMessage } from '@google/genai';

const App: React.FC = () => {
  useEffect(() => { dbService.init(); }, []);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => (localStorage.getItem('defendra_theme') as any) || 'dark');
  const [user, setUser] = useState<User | null>(null);
  const [guestMessageCount, setGuestMessageCount] = useState<number>(0);
  const [chatState, setChatState] = useState<ChatState>({
    messages: [{ 
      id: '1', 
      role: 'assistant', 
      content: "[SYSTEM]: INITIALIZING DEFENDRA NODE GATEWAY...\n\nPlease select an access protocol to proceed with the secure session buffer.", 
      timestamp: Date.now() 
    }],
    isLoading: false,
    error: null,
  });

  const [isLive, setIsLive] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  // Audio State
  const [speakingMsgId, setSpeakingMsgId] = useState<string | null>(null);
  const [loadingAudioMsgId, setLoadingAudioMsgId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Restore Session and Logs
  useEffect(() => {
    const restoreSession = async () => {
      const stored = localStorage.getItem('defendra_session');
      if (stored) {
        const sessionData = JSON.parse(stored);
        const dbRecord = await dbService.findUserByEmail(sessionData.email);
        if (dbRecord) {
          const { password_hash, ...clean } = dbRecord;
          setUser(clean);
          const history = await dbService.getChatHistory(clean.id);
          if (history.length > 0) {
            setChatState(prev => ({ ...prev, messages: history }));
          }
        } else {
          setShowAuth(true);
        }
      } else {
        setShowAuth(true);
      }
    };
    restoreSession();
  }, []);

  useEffect(() => {
    localStorage.setItem('defendra_theme', theme);
    document.body.style.backgroundColor = theme === 'light' ? '#f8fafc' : '#020617';
  }, [theme]);

  const scrollToBottom = useCallback(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), []);
  useEffect(() => { scrollToBottom(); }, [chatState.messages, scrollToBottom]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const stopAllAudio = () => {
    if (currentSourceRef.current) {
      currentSourceRef.current.stop();
      currentSourceRef.current = null;
    }
    setSpeakingMsgId(null);
  };

  const handleSpeak = async (message: Message) => {
    if (speakingMsgId === message.id) {
      stopAllAudio();
      return;
    }
    stopAllAudio();
    setLoadingAudioMsgId(message.id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const base64Audio = await gemini.generateSpeech(message.content);
      if (!base64Audio) throw new Error("Failed to generate speech buffer.");
      const audioData = gemini.decodeBase64(base64Audio);
      const audioBuffer = await gemini.decodeAudioData(audioData, audioContextRef.current);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => { if (speakingMsgId === message.id) setSpeakingMsgId(null); };
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(message.id);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(null);
    }
  };

  const handleAuthSuccess = async (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);
    setGuestMessageCount(0);

    const history = await dbService.getChatHistory(authenticatedUser.id);
    if (history.length > 0) {
      setChatState(prev => ({ ...prev, messages: history }));
    } else {
      setChatState({
        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[AUTH SUCCESS]: Node identification confirmed for @${authenticatedUser.username}.\n\nWelcome back, Operative. Vault logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleGuestChoice = () => {
    setShowAuth(false);
    setUser(null);
    setGuestMessageCount(0);
    setChatState({
      messages: [{ 
        id: '1', 
        role: 'assistant', 
        content: "[GUEST_BYPASS]: Ephemeral access protocol initiated. Session will terminate after 3 query cycles.", 
        timestamp: Date.now() 
      }],
      isLoading: false,
      error: null,
    });
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
    }

    const currentPlan = user?.plan || 'FREE';
    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: "",
        timestamp: Date.now()
      };

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: Image generated at ${imageSize} resolution.\n\nConfidence: 0.98`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo generation complete. Finalizing media buffers...\n\nConfidence: 0.95`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit applied successfully.\n\nConfidence: 0.92`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze this media file.", base64, file.type, currentPlan);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps', currentPlan);
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content, currentPlan);
      } else {
        setChatState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isLoading: false }));

        const stream = mode === 'lite' ? gemini.streamMessageLite(content, currentPlan) : gemini.streamMessage(content, currentPlan);

        for await (const chunk of stream) {
          responseContent += chunk;
          setChatState(prev => {
            const last = prev.messages[prev.messages.length - 1];
            if (last.id === assistantId) {
              const updatedMsg = { ...last, content: responseContent };
              return { ...prev, messages: [...prev.messages.slice(0, -1), updatedMsg] };
            }
            return prev;
          });
        }
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[WARNING]: Guest cycle limit reached. Further interactions require Node Authentication.";
        }
      }

      const finalAssistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      if (mode !== 'lite' && mode !== 'default') {
        setChatState(prev => ({
          ...prev,
          messages: [...prev.messages, finalAssistantMsg],
          isLoading: false
        }));
      } else {
        setChatState(prev => {
           const idx = prev.messages.findIndex(m => m.id === assistantId);
           if (idx !== -1) {
             const newMessages = [...prev.messages];
             newMessages[idx] = finalAssistantMsg;
             return { ...prev, messages: newMessages, isLoading: false };
           }
           return { ...prev, isLoading: false };
        });
      }

      if (user) {
        await dbService.saveMessage(user.id, finalAssistantMsg);
      }

    } catch (err: any) {
      setChatState(prev => ({ ...prev, error: `[SYSTEM ERROR]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[VAULT UPDATE]: Subscription status elevated to ${newPlan}. Clearance verified.\n\nConfidence: 1.00`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }
    if (isLive) { liveSessionRef.current?.close(); setIsLive(false); return; }
    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;
      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  const isLight = theme === 'light';

  return (
    <div className={`flex flex-col h-screen max-w-5xl mx-auto border-x relative transition-colors duration-300 ${isLight ? 'bg-slate-50 border-slate-200' : 'bg-slate-950 border-slate-900'}`}>
      <div className={`text-[10px] font-bold py-1 px-4 text-center uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-colors ${
        !user 
          ? 'bg-amber-500 text-slate-950' 
          : isLight ? 'bg-slate-200 text-slate-600' : 'bg-emerald-500 text-slate-950'
      }`}>
        <span>{user ? `Defendra Node v2.5 [@${user.username}]` : `GUEST_ACCESS_NODE [${3 - guestMessageCount}/3_CYCLES_REMAINING]`}</span>
        {isLive && <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></span> LIVE</span>}
      </div>

      <header className={`flex items-center justify-between px-6 py-4 border-b z-10 ${isLight ? 'bg-white border-slate-200' : 'bg-slate-900/50 border-slate-800'}`}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 border rounded-lg flex items-center justify-center shadow-lg ${isLight ? 'bg-slate-50 border-slate-200 text-blue-600' : 'bg-slate-950 border-emerald-500/40 text-emerald-500 shadow-emerald-500/20'}`}>
            <Icons.Shield />
          </div>
          <div><h1 className={`font-bold tracking-tight font-mono ${isLight ? 'text-slate-900' : 'text-slate-50'}`}>DEFENDRA</h1></div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} className="p-2 transition-transform active:scale-90">{isLight ? <Icons.Moon /> : <Icons.Sun />}</button>
          {user && <button onClick={() => setShowProfile(true)} className="p-2 hover:text-emerald-400 transition-colors"><Icons.User /></button>}
          {!user && (
            <button 
              onClick={() => setShowAuth(true)} 
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all active:scale-95 ${
                guestMessageCount >= 3 
                  ? 'bg-amber-500 text-slate-950 animate-pulse shadow-lg shadow-amber-500/20' 
                  : 'bg-emerald-500 text-slate-950'
              }`}
            >
              {guestMessageCount >= 3 ? 'AUTHENTICATE_REQUIRED' : 'INITIALIZE'}
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-2 scrollbar-hide">
        {chatState.messages.map(m => (
          <ChatMessage 
            key={m.id} 
            message={m} 
            isLight={isLight} 
            onSpeak={() => handleSpeak(m)}
            isSpeaking={speakingMsgId === m.id}
            isLoadingAudio={loadingAudioMsgId === m.id}
          />
        ))}
        {chatState.isLoading && <div className="text-[10px] font-mono animate-pulse text-emerald-500">PROCCESSING_QUERY...</div>}
        <div ref={messagesEndRef} />
      </main>

      <ChatInput 
        onSend={handleSendMessage} 
        onLiveToggle={handleLiveToggle} 
        disabled={chatState.isLoading} 
        isLight={isLight} 
        placeholder={!user ? `Guest cycle ${guestMessageCount + 1} of 3...` : "Input security query..."}
      />

      {showAuth && <AuthModal onSuccess={handleAuthSuccess} onGuestChoice={handleGuestChoice} isLight={isLight} />}
      {showProfile && user && <UserProfile user={user} onClose={() => setShowProfile(false)} onManageSubscription={() => { setShowProfile(false); setShowPlans(true); }} isLight={isLight} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} isLight={isLight} />}
    </div>
  );
};

