import React, { useState } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  onGuestChoice: () => void;
  isLight?: boolean;
}

type AuthView = 'choice' | 'signin' | 'signup' | 'forgot' | 'verification-challenge' | 'reset-password' | 'email-verification';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, onGuestChoice, isLight }) => {
  const [view, setView] = useState<AuthView>('choice');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    otp: ''
  });
  const [pendingUser, setPendingUser] = useState<User | null>(null);
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  const generateAndSetOtp = () => {
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(code);
    return code;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (view === 'signup') {
        setStatusMsg('PROVISIONING NODE...');
        if (!formData.username || !formData.email || !formData.password) {
          setError('Credentials required.');
        } else {
          const newUser = await dbService.createUser(formData.username, formData.email, formData.password);
          setPendingUser(newUser);
          generateAndSetOtp();
          await new Promise(r => setTimeout(r, 1500));
          setView('email-verification');
        }
      } else if (view === 'signin') {
        setStatusMsg('AUTHENTICATING...');
        const user = await dbService.findUserByEmail(formData.email);
        if (user && (user as any).password_hash === formData.password) {
          if (!user.isEmailConfirmed) {
            setPendingUser(user);
            generateAndSetOtp();
            setView('email-verification');
          } else {
            const { password_hash, ...cleanUser } = user as any;
            await dbService.recordLogin(cleanUser.id);
            onSuccess(cleanUser);
          }
        } else {
          setError('Invalid credentials.');
        }
      } else if (view === 'email-verification') {
        if (formData.otp === generatedOtp && pendingUser) {
          await dbService.confirmEmail(pendingUser.id);
          onSuccess({ ...pendingUser, isEmailConfirmed: true });
        } else {
          setError('Code mismatch.');
        }
      }
      // other logic handled by service...
    } catch (err) {
      setError('System malfunction.');
    } finally {
      setLoading(false);
      setStatusMsg('');
    }
  };

  const accentColor = 'text-emerald-400';
  const accentBg = 'bg-emerald-500';
  const accentBorder = 'border-emerald-500/30';

  if (view === 'choice') {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#020617]/95">
        <div className="w-full max-w-5xl flex flex-col items-center animate-in fade-in zoom-in-95 duration-700">

          {/* Header Section */}
          <div className="text-center mb-16 relative">
            <div className="flex justify-center mb-8">
              <div className={`w-20 h-20 rounded-3xl ${accentBg}/10 border ${accentBorder} flex items-center justify-center neon-glow-strong animate-pulse`}>
                <div className="scale-[2.5] text-emerald-400">
                  <Icons.Shield />
                </div>
              </div>
            </div>
            <h1 className="text-3xl md:text-4xl font-mono font-bold tracking-[0.25em] text-white mb-4 uppercase">
              INITIALIZE_NODE_PROTOCOL
            </h1>
            <p className="text-slate-400 text-sm tracking-widest uppercase font-mono max-w-md mx-auto leading-relaxed">
              Identity verification required to activate encrypted session buffer
            </p>
            <div className={`h-px w-48 mx-auto mt-8 bg-gradient-to-r from-transparent via-emerald-500/50 to-transparent`} />
          </div>

          {/* Authentication Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10 w-full max-w-4xl">

            {/* Agent Login Card */}
            <button
              onClick={() => setView('signin')}
              className="group relative flex flex-col items-center text-center p-12 glass-card rounded-[2.5rem] transition-all duration-500 hover:neon-glow hover:-translate-y-2 border-emerald-500/10 hover:border-emerald-500/40"
            >
              <div className="absolute top-0 right-0 p-4">
                <div className="text-[10px] font-mono text-emerald-500/40 uppercase tracking-widest">SECURE_LEVEL_4</div>
              </div>

              <div className="mb-8 p-6 rounded-full bg-emerald-500/5 text-emerald-400 group-hover:bg-emerald-500 group-hover:text-slate-950 transition-all duration-500 shadow-inner">
                <div className="scale-150">
                  <Icons.User />
                </div>
              </div>

              <h3 className="text-xl font-bold font-mono tracking-widest text-white mb-4 group-hover:text-emerald-400 transition-colors">AGENT_LOGIN</h3>
              <p className="text-xs text-slate-500 leading-relaxed tracking-wider font-mono">
                PERSISTENT SESSION AUDIT<br/>
                FULL NEURAL VAULT ACCESS<br/>
                ADVANCED THREAT ANALYSIS
              </p>

              <div className="mt-10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 text-emerald-500 text-[10px] font-mono tracking-widest">
                [ ACCESS PROTOCOL READY ]
              </div>
            </button>

            {/* Guest Access Card */}
            <button
              onClick={onGuestChoice}
              className="group relative flex flex-col items-center text-center p-12 glass-card rounded-[2.5rem] transition-all duration-500 hover:neon-glow hover:-translate-y-2 border-slate-700/30 hover:border-emerald-500/20"
            >
              <div className="absolute top-0 right-0 p-4">
                <div className="text-[10px] font-mono text-slate-600 uppercase tracking-widest">EPHEMERAL_LEVEL_1</div>
              </div>

              <div className="mb-8 p-6 rounded-full bg-slate-800/50 text-slate-400 group-hover:bg-white group-hover:text-slate-950 transition-all duration-500">
                <div className="scale-150">
                  <Icons.Zap />
                </div>
              </div>

              <h3 className="text-xl font-bold font-mono tracking-widest text-slate-200 mb-4 group-hover:text-white transition-colors">GUEST_ACCESS</h3>
              <p className="text-xs text-slate-500 leading-relaxed tracking-wider font-mono">
                3 QUERY CYCLE LIMIT<br/>
                AUTOMATED BUFFER PURGE<br/>
                TEMPORARY SESSION NODE
              </p>

              <div className="mt-10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 text-white text-[10px] font-mono tracking-widest">
                [ BYPASS PROTOCOL READY ]
              </div>
            </button>
          </div>

          {/* Footer Trust Line */}
          <div className="mt-20 flex items-center gap-3 text-slate-600">
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/40 animate-pulse" />
            <p className="text-[10px] font-mono uppercase tracking-[0.4em]">
              Secured by Defendra Vault v2.5.0
            </p>
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/40 animate-pulse" />
          </div>

        </div>
      </div>
    );
  }

  // Common UI for login/signup forms with the refined aesthetic
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#020617]/98 backdrop-blur-xl">
      <div className="w-full max-w-md glass-card rounded-[2rem] border-emerald-500/20 neon-glow overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">

        <div className="p-8 border-b border-emerald-500/10 text-center relative bg-emerald-500/[0.02]">
          <button 
            onClick={() => setView('choice')}
            className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500 hover:text-emerald-400 transition-all duration-300"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" className="w-5 h-5">
              <path d="M19 12H5M12 19l-7-7 7-7" />
            </svg>
          </button>

          <div className="flex justify-center mb-4">
            <div className="w-12 h-12 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-400 border border-emerald-500/20">
              <Icons.Shield />
            </div>
          </div>
          <h2 className="text-xl font-bold font-mono tracking-widest text-white uppercase">
            {view === 'signin' ? 'NODE_AUTH' : view === 'signup' ? 'NODE_PROVISION' : 'IDENTITY_VERIFY'}
          </h2>
          <p className="text-[9px] text-emerald-500/50 mt-1 uppercase tracking-[0.3em] font-mono">
            {loading ? statusMsg : 'Credentials Required'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="p-10 space-y-6">
          {error && (
            <div className="bg-red-500/10 border border-red-500/30 text-red-500 p-4 rounded-xl text-[10px] font-mono uppercase tracking-widest animate-pulse">
              [SYSTEM_ERROR]: {error}
            </div>
          )}

          {view === 'signup' && (
            <div>
              <label className="block text-[10px] font-mono font-bold uppercase mb-2 tracking-widest text-slate-500">Agent Name</label>
              <input
                type="text"
                className="w-full bg-slate-950/50 border border-slate-800 rounded-xl px-4 py-3 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-800"
                placeholder="OPERATIVE_ID"
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value })}
              />
            </div>
          )}

          <div>
            <label className="block text-[10px] font-mono font-bold uppercase mb-2 tracking-widest text-slate-500">Node Email</label>
            <input
              type="email"
              className="w-full bg-slate-950/50 border border-slate-800 rounded-xl px-4 py-3 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-800"
              placeholder="OP@SECURE.NODE"
              value={formData.email}
              onChange={e => setFormData({ ...formData, email: e.target.value })}
            />
          </div>

          {view === 'email-verification' ? (
             <div>
              <label className="block text-[10px] font-mono font-bold uppercase mb-2 tracking-widest text-slate-500">Decrypt Challenge Code</label>
              <input
                type="text"
                className="w-full bg-slate-950/50 border border-emerald-500/30 rounded-xl px-4 py-4 text-2xl font-mono text-center tracking-[0.5em] text-emerald-400 focus:border-emerald-500 focus:outline-none transition-all"
                placeholder="000000"
                maxLength={6}
                value={formData.otp}
                onChange={e => setFormData({ ...formData, otp: e.target.value })}
              />
              <div className="mt-4 p-4 rounded-xl border border-emerald-500/20 bg-emerald-500/5">
                <p className="text-[10px] font-mono text-emerald-500 leading-tight">
                  Outgoing challenge intercepted. Code: <span className="font-bold underline">{generatedOtp}</span>
                </p>
                <button type="button" onClick={() => setFormData({...formData, otp: generatedOtp})} className="mt-2 text-[9px] font-bold text-emerald-400 uppercase tracking-widest hover:underline">[ AUTO_FILL ]</button>
              </div>
            </div>
          ) : (
            <div>
              <label className="block text-[10px] font-mono font-bold uppercase mb-2 tracking-widest text-slate-500">Security Key</label>
              <input
                type="password"
                className="w-full bg-slate-950/50 border border-slate-800 rounded-xl px-4 py-3 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-800"
                placeholder="••••••••"
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-mono font-bold py-4 rounded-xl transition-all active:scale-[0.98] text-xs tracking-[0.3em] uppercase shadow-lg shadow-emerald-500/20"
          >
            {loading ? 'EXECUTING...' : 'INITIATE_AUTH'}
          </button>

          <div className="text-center">
            <button
              type="button"
              onClick={() => {
                setView(view === 'signin' ? 'signup' : 'signin');
                setError('');
              }}
              className="text-[10px] font-mono uppercase tracking-widest text-slate-600 hover:text-emerald-400 transition-colors"
            >
              {view === 'signin' ? '[ NEW_NODE_PROVISION ]' : '[ AUTH_EXISTING_NODE ]'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

