  return (
    <div className={`flex w-full mb-8 ${isUser ? 'justify-end' : 'justify-start'} group animate-in fade-in slide-in-from-bottom-3 duration-500`}>
      <div className={`flex max-w-[85%] md:max-w-[80%] ${isUser ? 'flex-row-reverse' : 'flex-row'} gap-5`}>
        <div className={`flex-shrink-0 w-12 h-12 rounded-2xl flex items-center justify-center border transition-all duration-300 ${
          isUser 
            ? 'bg-slate-900 border-slate-700/50 text-emerald-400'
            : 'bg-slate-900 border-emerald-500/20 text-emerald-500 shadow-lg shadow-emerald-500/5'
