            {message.groundingLinks && message.groundingLinks.length > 0 && (
              <div className="mt-4 space-y-2 border-t border-emerald-500/10 pt-4">
                <p className="text-[10px] uppercase tracking-[0.2em] text-emerald-500/60 font-bold mb-3">Verification Sources:</p>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {message.groundingLinks.map((link, i) => (
