            <span className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] font-mono opacity-60">
              {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
