            {!isUser && onSpeak && (
              <button
                onClick={() => onSpeak(message.content)}
                className={`transition-all duration-300 p-1.5 rounded-lg ${
                  isLoadingAudio 
                    ? 'text-emerald-500 animate-spin opacity-100' 
                    : isSpeaking 
                      ? 'text-emerald-400 bg-emerald-500/10 scale-110 opacity-100 neon-glow' 
                      : 'text-slate-600 hover:text-emerald-400 hover:bg-emerald-500/5 opacity-0 group-hover:opacity-100'
                }`}
                title={isLoadingAudio ? "Generating..." : isSpeaking ? "Stop" : "Speak"}
                disabled={isLoadingAudio}
              >
                {isLoadingAudio ? (
                  <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <path d="M12 2v4m0 12v4M4.93 4.93l2.83 2.83m8.48 8.48l2.83 2.83M2 12h4m12 0h4M4.93 19.07l2.83-2.83m8.48-8.48l2.83-2.83" />
                  </svg>
                ) : (
                  <Icons.Speaker />
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../constants';

export type InputMode = 'default' | 'lite' | 'thinking' | 'search' | 'maps' | 'image' | 'video' | 'edit';

interface ChatInputProps {
  onSend: (message: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => void;
  onLiveToggle: () => void;
  disabled: boolean;
  placeholder?: string;
  isLight?: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSend, onLiveToggle, disabled, placeholder = "Input security query...", isLight }) => {
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<InputMode>('default');
  const [imageSize, setImageSize] = useState<'1K' | '2K' | '4K'>('1K');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [input]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((input.trim() || selectedFile) && !disabled) {
      onSend(input.trim(), mode, selectedFile || undefined, mode === 'image' ? imageSize : undefined);
      setInput('');
      setSelectedFile(null);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  return (
    <div className="bg-slate-950/60 border-t border-slate-800/50 backdrop-blur-2xl p-6 relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-4">

        {/* Mode Selector Bar */}
        <div className="flex items-center gap-2 overflow-x-auto scrollbar-hide py-1">
          {[
            { id: 'default', label: 'Pro', icon: <Icons.Shield /> },
            { id: 'lite', label: 'Lite', icon: <Icons.Zap /> },
            { id: 'thinking', label: 'Think', icon: <Icons.Bot /> },
            { id: 'search', label: 'Search', icon: <Icons.Search /> },
            { id: 'maps', label: 'Maps', icon: <Icons.Map /> },
            { id: 'image', label: 'Gen', icon: <Icons.Image /> },
            { id: 'video', label: 'Veo', icon: <Icons.Movie /> },
            { id: 'edit', label: 'Edit', icon: <Icons.Image /> },
          ].map(m => (
            <button
              key={m.id}
              onClick={() => setMode(m.id as InputMode)}
              className={`flex-shrink-0 px-4 py-2 rounded-xl border text-[10px] font-bold uppercase tracking-[0.2em] flex items-center gap-2.5 transition-all duration-300 ${
                mode === m.id 
                  ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/40 shadow-lg shadow-emerald-500/5'
                  : 'bg-slate-900/50 border-slate-800/50 text-slate-500 hover:text-slate-300 hover:border-slate-700'
              }`}
            >
              <div className="scale-90">{m.icon}</div>
              {m.label}
            </button>
          ))}
          <div className="w-px h-6 bg-slate-800 mx-2 flex-shrink-0" />
          <button
            onClick={onLiveToggle}
            className="flex-shrink-0 px-4 py-2 rounded-xl bg-red-500/5 border border-red-500/20 text-red-400 text-[10px] font-bold uppercase tracking-[0.2em] flex items-center gap-2.5 transition-all hover:bg-red-500/10 hover:border-red-500/40"
          >
            <div className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse" />
            LIVE
          </button>
        </div>

        {/* Input Form */}
        <form onSubmit={handleSubmit} className="relative flex items-end gap-3 group">
          <div className="relative flex-1 bg-slate-900/40 border border-slate-800/80 rounded-2xl p-1.5 focus-within:border-emerald-500/40 transition-all duration-300">
            {selectedFile && (
              <div className="flex items-center gap-3 p-3 mb-2 bg-emerald-500/5 rounded-xl border border-emerald-500/10 animate-in slide-in-from-bottom-2">
                <div className="text-emerald-400"><Icons.Lock /></div>
                <span className="text-[11px] text-emerald-300 font-mono truncate flex-1">{selectedFile.name}</span>
                <button onClick={() => setSelectedFile(null)} className="text-slate-500 hover:text-red-400 p-1">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="w-3.5 h-3.5"><path d="M18 6L6 18M6 6l12 12" /></svg>
                </button>
              </div>
            )}

            <div className="flex items-center px-4">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={mode === 'image' ? "Describe vision for generation..." : placeholder}
                disabled={disabled}
                className="w-full py-4 bg-transparent border-none focus:outline-none focus:ring-0 text-sm font-mono text-slate-200 placeholder:text-slate-600 resize-none scrollbar-hide leading-relaxed"
                rows={1}
              />
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="p-3 text-slate-500 hover:text-emerald-400 transition-colors"
                title="Attach Media"
              >
                <Icons.Lock />
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} hidden accept="image/*,video/*" />
            </div>
          </div>

          {mode === 'image' && (
            <div className="flex flex-col gap-1.5">
              <label className="text-[8px] font-mono font-bold uppercase tracking-widest text-slate-600 px-1">Res</label>
              <select 
                value={imageSize} 
                onChange={(e) => setImageSize(e.target.value as any)}
                className="bg-slate-900 border border-slate-800 rounded-xl px-4 py-4 text-[11px] font-bold text-emerald-400 focus:outline-none appearance-none cursor-pointer hover:border-emerald-500/30 transition-all"
              >
                <option value="1K">1K</option>
                <option value="2K">2K</option>
                <option value="4K">4K</option>
              </select>
            </div>
          )}

          <button
            type="submit"
            disabled={(!input.trim() && !selectedFile) || disabled}
            className={`p-4 rounded-2xl border transition-all duration-500 h-[58px] w-[58px] flex items-center justify-center ${
              (input.trim() || selectedFile) && !disabled 
                ? 'bg-emerald-500 text-slate-950 border-emerald-400 shadow-xl shadow-emerald-500/20 active:scale-95' 
                : 'bg-slate-900 border-slate-800 text-slate-700 opacity-50 grayscale'
            }`}
          >
            <div className="scale-110"><Icons.Send /></div>
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatInput;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatState, User, PlanType } from './types';
import { gemini } from './services/geminiService';
import { dbService } from './services/dbService';
import { Icons } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput, { InputMode } from './components/ChatInput';
import AuthModal from './components/AuthModal';
import PlanSelection from './components/PlanSelection';
import UserProfile from './components/UserProfile';
import { LiveServerMessage } from '@google/genai';

const App: React.FC = () => {
  useEffect(() => { dbService.init(); }, []);

  const [user, setUser] = useState<User | null>(null);
  const [guestMessageCount, setGuestMessageCount] = useState<number>(0);
  const [chatState, setChatState] = useState<ChatState>({
    messages: [{ 
      id: '1', 
      role: 'assistant', 
      content: "[SYSTEM_CORE]: INITIALIZING DEFENDRA ENTERPRISE GATEWAY...\n\nPlease select an authentication protocol to activate your secure session buffer.", 
      timestamp: Date.now() 
    }],
    isLoading: false,
    error: null,
  });

  const [isLive, setIsLive] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [showPlans, setShowPlans] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  // Audio State
  const [speakingMsgId, setSpeakingMsgId] = useState<string | null>(null);
  const [loadingAudioMsgId, setLoadingAudioMsgId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Restore Session and Logs
  useEffect(() => {
    const restoreSession = async () => {
      const stored = localStorage.getItem('defendra_session');
      if (stored) {
        const sessionData = JSON.parse(stored);
        const dbRecord = await dbService.findUserByEmail(sessionData.email);
        if (dbRecord) {
          const { password_hash, ...clean } = dbRecord;
          setUser(clean);
          const history = await dbService.getChatHistory(clean.id);
          if (history.length > 0) {
            setChatState(prev => ({ ...prev, messages: history }));
          }
        } else {
          setShowAuth(true);
        }
      } else {
        setShowAuth(true);
      }
    };
    restoreSession();
  }, []);

  const scrollToBottom = useCallback(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, []);

  useEffect(() => { scrollToBottom(); }, [chatState.messages, scrollToBottom]);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const stopAllAudio = () => {
    if (currentSourceRef.current) {
      currentSourceRef.current.stop();
      currentSourceRef.current = null;
    }
    setSpeakingMsgId(null);
  };

  const handleSpeak = async (message: Message) => {
    if (speakingMsgId === message.id) {
      stopAllAudio();
      return;
    }
    stopAllAudio();
    setLoadingAudioMsgId(message.id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const base64Audio = await gemini.generateSpeech(message.content);
      if (!base64Audio) throw new Error("Audio buffer generation failed.");
      const audioData = gemini.decodeBase64(base64Audio);
      const audioBuffer = await gemini.decodeAudioData(audioData, audioContextRef.current);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => { if (speakingMsgId === message.id) setSpeakingMsgId(null); };
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(message.id);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      setLoadingAudioMsgId(null);
      setSpeakingMsgId(null);
    }
  };

  const handleAuthSuccess = async (authenticatedUser: User) => {
    setUser(authenticatedUser);
    localStorage.setItem('defendra_session', JSON.stringify(authenticatedUser));
    setShowAuth(false);
    setGuestMessageCount(0);

    const history = await dbService.getChatHistory(authenticatedUser.id);
    if (history.length > 0) {
      setChatState(prev => ({ ...prev, messages: history }));
    } else {
      setChatState({
        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[NODE_AUTHENTICATED]: Operative identity verified as @${authenticatedUser.username}.\n\nWelcome back. Secure neural pathways established. Your session logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleGuestChoice = () => {
    setShowAuth(false);
    setUser(null);
    setGuestMessageCount(0);
    setChatState({
      messages: [{ 
        id: '1', 
        role: 'assistant', 
        content: "[EPHEMERAL_ACCESS]: Session node initiated. Automated purge sequence will trigger after 3 query cycles.", 
        timestamp: Date.now() 
      }],
      isLoading: false,
      error: null,
    });
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
    }

    const currentPlan = user?.plan || 'FREE';
    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: "",
        timestamp: Date.now()
      };

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: High-fidelity generation complete at ${imageSize} resolution.\n\nConfidence: 0.99`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo temporal buffer compiled successfully.\n\nConfidence: 0.96`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit protocol executed successfully.\n\nConfidence: 0.94`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze media stream.", base64, file.type, currentPlan);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps', currentPlan);
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content, currentPlan);
      } else {
        setChatState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isLoading: false }));

        const stream = mode === 'lite' ? gemini.streamMessageLite(content, currentPlan) : gemini.streamMessage(content, currentPlan);

        for await (const chunk of stream) {
          responseContent += chunk;
          setChatState(prev => {
            const last = prev.messages[prev.messages.length - 1];
            if (last.id === assistantId) {
              const updatedMsg = { ...last, content: responseContent };
              return { ...prev, messages: [...prev.messages.slice(0, -1), updatedMsg] };
            }
            return prev;
          });
        }
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[NOTICE]: Session limit reached. Persistance requires Node Authentication.";
        }
      }

      const finalAssistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      if (mode !== 'lite' && mode !== 'default') {
        setChatState(prev => ({
          ...prev,
          messages: [...prev.messages, finalAssistantMsg],
          isLoading: false
        }));
      } else {
        setChatState(prev => {
           const idx = prev.messages.findIndex(m => m.id === assistantId);
           if (idx !== -1) {
             const newMessages = [...prev.messages];
             newMessages[idx] = finalAssistantMsg;
             return { ...prev, messages: newMessages, isLoading: false };
           }
           return { ...prev, isLoading: false };
        });
      }

      if (user) {
        await dbService.saveMessage(user.id, finalAssistantMsg);
      }

    } catch (err: any) {
      setChatState(prev => ({ ...prev, error: `[FAULT]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[CLEARANCE_UPDATED]: Subscription profile elevated to ${newPlan}. Encryption keys re-initialized.\n\nConfidence: 1.00`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }
    if (isLive) { liveSessionRef.current?.close(); setIsLive(false); return; }
    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;
      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  return (
    <div className="flex flex-col h-screen max-w-[1440px] mx-auto relative transition-all duration-700 bg-slate-950 shadow-2xl overflow-hidden">

      {/* Dynamic Status Bar */}
      <div className={`text-[9px] font-bold py-1 px-6 flex items-center justify-between uppercase tracking-[0.4em] transition-all duration-500 font-mono border-b border-slate-900 ${
        !user 
          ? 'bg-amber-500/10 text-amber-500' 
          : 'bg-emerald-500/5 text-emerald-500/80'
      }`}>
        <div className="flex items-center gap-4">
          <span className="flex items-center gap-1.5">
            <span className={`w-1.5 h-1.5 rounded-full ${user ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`} />
            NODE_STATUS: ONLINE
          </span>
          <span className="opacity-40">|</span>
          <span>{user ? `OPERATIVE: @${user.username}` : `GUEST_BYPASS_MODE [${3 - guestMessageCount} CYCLES]`}</span>
        </div>
        <div className="hidden md:flex items-center gap-4 opacity-60">
          <span>LATENCY: 12ms</span>
          <span>VAULT: ENCRYPTED</span>
        </div>
      </div>

      {/* Enterprise Header */}
