                : 'bg-red-500/10 border-red-500/30 text-red-500'
            }`}>
              [PROTOCOL_NOTICE]: {error}
              {error.includes('verified') && (
                <button type="button" onClick={() => setView('email-verification')} className="block mt-2 text-emerald-400 hover:underline">[ VERIFY_NOW ]</button>
