export default AuthModal;

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  onGuestChoice: () => void;
  isLight?: boolean;
}

type AuthView = 
  | 'choice' 
  | 'signin' 
  | 'signup' 
  | 'email-verification'
  | 'forgot-email' 
  | 'forgot-otp' 
  | 'forgot-new'
  | 'success';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, onGuestChoice, isLight }) => {
  const [view, setView] = useState<AuthView>('choice');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
  });

  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

  const [pendingUser, setPendingUser] = useState<User | null>(null);
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  // Auto-focus first input on view change
  useEffect(() => {
    if (view === 'signin' || view === 'signup' || view === 'forgot-email') {
      const firstInput = document.querySelector('input');
      firstInput?.focus();
    } else if (view === 'email-verification' || view === 'forgot-otp') {
      otpRefs.current[0]?.focus();
    }
  }, [view]);

  const generateAndSetOtp = () => {
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(code);
    return code;
  };

  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    // Move focus forward
    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const resetOtp = () => setOtp(['', '', '', '', '', '']);

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMsg('AUTHENTICATING...');

    try {
      const user = await dbService.findUserByEmail(formData.email);
      if (!user) {
        setError('No account found with this email address.');
        return;
      }

      if ((user as any).password_hash !== formData.password) {
        setError('The password you entered is incorrect.');
        return;
      }

      if (!user.isEmailConfirmed) {
        setPendingUser(user);
        generateAndSetOtp();
        setView('email-verification');
      } else {
        const { password_hash, ...cleanUser } = user as any;
        await dbService.recordLogin(cleanUser.id);
        onSuccess(cleanUser);
      }
    } catch (err) {
      setError('A system malfunction occurred.');
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMsg('PROVISIONING NODE...');

    try {
      const existing = await dbService.findUserByEmail(formData.email);
      if (existing) {
        setError('This email is already registered. Please sign in.');
        return;
      }

      const newUser = await dbService.createUser(formData.username, formData.email, formData.password);
      setPendingUser(newUser);
      generateAndSetOtp();
      setView('email-verification');
    } catch (err) {
      setError('Account creation failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerification = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const code = otp.join('');
    if (code.length < 6) {
      setError('Please enter the full 6-digit code.');
      return;
    }

    if (code === generatedOtp && pendingUser) {
      setLoading(true);
      await dbService.confirmEmail(pendingUser.id);
      setSuccessMsg('Email verified successfully');
      setTimeout(() => onSuccess({ ...pendingUser, isEmailConfirmed: true }), 1500);
    } else {
      setError('The code doesn’t match. Please try again.');
    }
  };

  const handleForgotEmail = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    const user = await dbService.findUserByEmail(formData.email);
    if (!user) {
      setError('No account found with this email.');
      setLoading(false);
    } else {
      generateAndSetOtp();
      setView('forgot-otp');
      setLoading(false);
    }
  };

  const handleForgotOtp = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (otp.join('') === generatedOtp) {
      setView('forgot-new');
    } else {
      setError('The code doesn’t match. Please try again.');
    }
  };

  const handleResetPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match.');
      return;
    }
    if (formData.password.length < 8) {
      setError('Password must be at least 8 characters.');
      return;
    }
    setLoading(true);
    const success = await dbService.updateUserPassword(formData.email, formData.password);
    if (success) {
      setSuccessMsg('Your password has been updated successfully.');
      setTimeout(() => setView('signin'), 2000);
    } else {
      setError('Password reset failed.');
    }
    setLoading(false);
  };

  const renderOtpInput = () => (
    <div className="flex justify-between gap-2 mb-6">
      {otp.map((digit, i) => (
        <input
          key={i}
          ref={el => otpRefs.current[i] = el}
          type="text"
          maxLength={1}
          value={digit}
          onChange={e => handleOtpChange(i, e.target.value)}
          onKeyDown={e => handleOtpKeyDown(i, e)}
          className={`w-12 h-14 bg-slate-950/50 border rounded-xl text-center text-xl font-mono text-emerald-400 focus:outline-none transition-all ${
            error ? 'border-amber-500/50' : digit ? 'border-emerald-500/50' : 'border-slate-800'
