                  placeholder="SECURITY KEY"
                  value={formData.password}
                  onChange={e => setFormData({ ...formData, password: e.target.value })}
                />
              </div>
              <button type="submit" disabled={loading} className="w-full bg-emerald-500 text-slate-950 font-mono font-bold py-4 rounded-xl transition-all hover:bg-emerald-400 active:scale-95 text-xs tracking-widest uppercase">
