                </p>
              </div>

              {renderOtpInput()}

              <div className="space-y-4">
                <button type="submit" disabled={loading} className="w-full bg-emerald-500 text-slate-950 font-mono font-bold py-4 rounded-xl transition-all hover:bg-emerald-400 active:scale-95 text-xs tracking-widest uppercase shadow-lg shadow-emerald-500/20">
