        messages: [{ 
          id: `AUTH-${Date.now()}`, 
          role: 'assistant', 
          content: `[NODE_AUTHENTICATED]: Operative identity verified as @${authenticatedUser.username}.\n\nWelcome back. Secure neural pathways established. Your session logs are now accessible.`, 
          timestamp: Date.now() 
        }],
        isLoading: false,
        error: null
      });
    }
  };

  const handleGuestChoice = () => {
    setShowAuth(false);
    setUser(null);
    setGuestMessageCount(0);
    setChatState({
      messages: [{ 
        id: '1', 
        role: 'assistant', 
        content: "[EPHEMERAL_ACCESS]: Session node initiated. Automated purge sequence will trigger after 3 query cycles.", 
        timestamp: Date.now() 
      }],
      isLoading: false,
      error: null,
    });
  };

  const handleSendMessage = async (content: string, mode: InputMode, file?: File, imageSize?: '1K' | '2K' | '4K') => {
    if (!user && guestMessageCount >= 3) {
      setShowAuth(true);
      return;
