      id: Date.now().toString(), 
      role: 'user', 
      content: content || (file ? `Analyze ${file.name}` : ''), 
      timestamp: Date.now() 
    };

    setChatState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isLoading: true }));

    if (user) {
      await dbService.saveMessage(user.id, userMsg);
    }

    try {
      const assistantId = (Date.now() + 1).toString();
      let responseContent = "";
      let mediaUrl = "";
      let mediaType: 'image' | 'video' | undefined = undefined;
      let groundingLinks: any[] = [];

      const assistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: "",
        timestamp: Date.now()
      };

      if (mode === 'image') {
        mediaUrl = await gemini.generateImage(content, imageSize || '1K');
        mediaType = 'image';
        responseContent = `[VAULT]: High-fidelity generation complete at ${imageSize} resolution.\n\nConfidence: 0.99`;
      } else if (mode === 'video') {
        const base64 = file ? await fileToBase64(file) : undefined;
        mediaUrl = await gemini.generateVideo(content, base64);
        mediaType = 'video';
        responseContent = `[VAULT]: Veo temporal buffer compiled successfully.\n\nConfidence: 0.96`;
      } else if (mode === 'edit' && file) {
        const base64 = await fileToBase64(file);
        mediaUrl = await gemini.editImage(content, base64);
        mediaType = 'image';
        responseContent = `[VAULT]: Neural edit protocol executed successfully.\n\nConfidence: 0.94`;
      } else if (file) {
        const base64 = await fileToBase64(file);
        responseContent = await gemini.analyzeMedia(content || "Analyze media stream.", base64, file.type, currentPlan);
      } else if (mode === 'search' || mode === 'maps') {
        const result = await gemini.generateGroundedContent(content, mode === 'search' ? 'googleSearch' : 'googleMaps', currentPlan);
        responseContent = result.text;
        groundingLinks = result.links;
      } else if (mode === 'thinking') {
        responseContent = await gemini.generateWithThinking(content, currentPlan);
      } else {
        setChatState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isLoading: false }));

        const stream = mode === 'lite' ? gemini.streamMessageLite(content, currentPlan) : gemini.streamMessage(content, currentPlan);

        for await (const chunk of stream) {
          responseContent += chunk;
          setChatState(prev => {
            const last = prev.messages[prev.messages.length - 1];
            if (last.id === assistantId) {
              const updatedMsg = { ...last, content: responseContent };
              return { ...prev, messages: [...prev.messages.slice(0, -1), updatedMsg] };
            }
            return prev;
          });
        }
      }

      if (!user) {
        const newCount = guestMessageCount + 1;
        setGuestMessageCount(newCount);
        if (newCount === 3) {
          responseContent += "\n\n[NOTICE]: Session limit reached. Persistance requires Node Authentication.";
        }
      }

      const finalAssistantMsg: Message = {
        id: assistantId,
        role: 'assistant',
        content: responseContent,
        mediaUrl,
        mediaType,
        groundingLinks,
        timestamp: Date.now()
      };

      if (mode !== 'lite' && mode !== 'default') {
        setChatState(prev => ({
          ...prev,
          messages: [...prev.messages, finalAssistantMsg],
          isLoading: false
        }));
      } else {
        setChatState(prev => {
           const idx = prev.messages.findIndex(m => m.id === assistantId);
           if (idx !== -1) {
             const newMessages = [...prev.messages];
             newMessages[idx] = finalAssistantMsg;
             return { ...prev, messages: newMessages, isLoading: false };
           }
           return { ...prev, isLoading: false };
        });
      }

      if (user) {
        await dbService.saveMessage(user.id, finalAssistantMsg);
      }

    } catch (err: any) {
      // Fix: Handle specific API error by re-prompting for key selection as required by guidelines
      if (err.message?.includes("Requested entity was not found.") && typeof window.aistudio !== 'undefined') {
        await window.aistudio.openSelectKey();
      }
      setChatState(prev => ({ ...prev, error: `[FAULT]: ${err.message}`, isLoading: false }));
    }
  };

  const handleUpgrade = async (newPlan: PlanType) => {
    if (!user) return;
    setChatState(prev => ({ ...prev, isLoading: true }));
    const success = await dbService.updateUserPlan(user.id, newPlan);
    if (success) {
      const updatedUser = { ...user, plan: newPlan };
      setUser(updatedUser);
      localStorage.setItem('defendra_session', JSON.stringify(updatedUser));
      setShowPlans(false);
      const logMsg: Message = {
        id: `PLAN-${Date.now()}`,
        role: 'assistant',
        content: `[CLEARANCE_UPDATED]: Subscription profile elevated to ${newPlan}. Encryption keys re-initialized.\n\nConfidence: 1.00`,
        timestamp: Date.now(),
      };
      setChatState(prev => ({
        ...prev,
        messages: [...prev.messages, logMsg],
        isLoading: false
      }));
      await dbService.saveMessage(user.id, logMsg);
    }
  };

  const handleLiveToggle = async () => {
    if (!user) { setShowAuth(true); return; }
    if (isLive) { liveSessionRef.current?.close(); setIsLive(false); return; }
    try {
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      let nextStartTime = 0;
      const sessionPromise = gemini.connectLive({
        onopen: () => {
          const source = audioContextRef.current!.createMediaStreamSource(stream);
          const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const input = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(input.length);
            for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
            sessionPromise.then(s => s.sendRealtimeInput({ 
              media: { data: gemini.encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } 
            }));
          };
          source.connect(processor);
          processor.connect(audioContextRef.current!.destination);
          setIsLive(true);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const audio = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const buffer = await gemini.decodeAudioData(gemini.decodeBase64(audio), audioContextRef.current!);
            const source = audioContextRef.current!.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current!.destination);
            nextStartTime = Math.max(nextStartTime, audioContextRef.current!.currentTime);
            source.start(nextStartTime);
            nextStartTime += buffer.duration;
            sourcesRef.current.add(source);
          }
          if (msg.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false),
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { console.error(e); }
  };

  return (
    <div className="flex flex-col h-screen max-w-[1440px] mx-auto relative transition-all duration-700 bg-slate-950 shadow-2xl overflow-hidden">

      {/* Dynamic Status Bar */}
      <div className={`text-[9px] font-bold py-1 px-6 flex items-center justify-between uppercase tracking-[0.4em] transition-all duration-500 font-mono border-b border-slate-900 ${
        !user 
          ? 'bg-amber-500/10 text-amber-500' 
          : 'bg-emerald-500/5 text-emerald-500/80'
      }`}>
        <div className="flex items-center gap-4">
          <span className="flex items-center gap-1.5">
            <span className={`w-1.5 h-1.5 rounded-full ${user ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`} />
            NODE_STATUS: ONLINE
          </span>
          <span className="opacity-40">|</span>
          <span>{user ? `OPERATIVE: @${user.username}` : `GUEST_BYPASS_MODE [${3 - guestMessageCount} CYCLES]`}</span>
        </div>
        <div className="hidden md:flex items-center gap-4 opacity-60">
          <span>LATENCY: 12ms</span>
          <span>VAULT: ENCRYPTED</span>
        </div>
      </div>

      {/* Enterprise Header */}
      <header className="flex items-center justify-between px-8 py-5 border-b border-slate-900/80 bg-slate-950/80 backdrop-blur-xl z-20">
        <div className="flex items-center gap-5 group cursor-default">
          <div className="w-11 h-11 bg-slate-900 border border-emerald-500/20 rounded-xl flex items-center justify-center text-emerald-500 shadow-lg shadow-emerald-500/5 group-hover:border-emerald-500/40 transition-all duration-300">
            <div className="scale-110"><Icons.Shield /></div>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-[0.2em] font-mono text-white mb-0.5">DEFENDRA</h1>
            <p className="text-[9px] text-emerald-500/40 uppercase tracking-[0.4em] font-mono">Cognitive Security Systems</p>
          </div>
        </div>

        <div className="flex items-center gap-5">
          {user && (
            <button 
              onClick={() => setShowProfile(true)} 
              className="group flex items-center gap-3 px-4 py-2 rounded-xl bg-slate-900 border border-slate-800 hover:border-emerald-500/30 transition-all duration-300"
            >
              <div className="text-emerald-400 group-hover:scale-110 transition-transform"><Icons.User /></div>
              <span className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest hidden sm:inline">VAULT_ACCESS</span>
            </button>
          )}
          {!user && (
            <button 
              onClick={() => setShowAuth(true)} 
              className="relative px-6 py-2.5 rounded-xl text-[10px] font-bold font-mono tracking-widest uppercase transition-all duration-500 bg-emerald-500 text-slate-950 hover:bg-emerald-400 active:scale-95 shadow-lg shadow-emerald-500/20"
            >
              INITIALIZE_GATEWAY
            </button>
          )}
        </div>
      </header>

      {/* Main Interaction Surface */}
      <main className="flex-1 overflow-y-auto p-6 md:p-12 space-y-4 scrollbar-hide bg-gradient-to-b from-slate-950 to-[#020617]">
        <div className="max-w-4xl mx-auto w-full">
          {chatState.messages.map(m => (
            <ChatMessage 
              key={m.id} 
              message={m} 
              onSpeak={() => handleSpeak(m)}
              isSpeaking={speakingMsgId === m.id}
              isLoadingAudio={loadingAudioMsgId === m.id}
            />
          ))}
          {chatState.isLoading && (
            <div className="flex items-center gap-3 text-[10px] font-mono text-emerald-500/60 uppercase tracking-[0.3em] py-4 animate-in fade-in">
              <div className="w-4 h-px bg-emerald-500/40 animate-pulse" />
              PROCESSOR_EXECUTING_QUERY
              <div className="flex gap-1">
                <span className="animate-bounce delay-100">.</span>
                <span className="animate-bounce delay-200">.</span>
                <span className="animate-bounce delay-300">.</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </main>

      <div className="max-w-5xl mx-auto w-full px-6">
        <ChatInput 
          onSend={handleSendMessage} 
          onLiveToggle={handleLiveToggle} 
          disabled={chatState.isLoading} 
          placeholder={!user ? `Guest Protocol Cycle ${guestMessageCount + 1}/3...` : "Input enterprise-grade security query..."}
        />
      </div>

      {/* Overlay Layers */}
      {showAuth && <AuthModal onSuccess={handleAuthSuccess} onGuestChoice={handleGuestChoice} />}
      {showProfile && user && <UserProfile user={user} onClose={() => setShowProfile(false)} onManageSubscription={() => { setShowProfile(false); setShowPlans(true); }} />}
      {showPlans && <PlanSelection currentPlan={user?.plan || 'FREE'} onUpgrade={handleUpgrade} onClose={() => setShowPlans(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../constants';
import { User } from '../types';
import { dbService } from '../services/dbService';

interface AuthModalProps {
  onSuccess: (user: User) => void;
  onGuestChoice: () => void;
  isLight?: boolean;
}

type AuthView = 
  | 'choice' 
  | 'signin' 
  | 'signup' 
  | 'email-verification'
  | 'forgot-email' 
  | 'forgot-otp' 
  | 'forgot-new'
  | 'success';

const AuthModal: React.FC<AuthModalProps> = ({ onSuccess, onGuestChoice, isLight }) => {
  const [view, setView] = useState<AuthView>('choice');
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
  });

  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

  const [pendingUser, setPendingUser] = useState<User | null>(null);
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');

  useEffect(() => {
    if (view === 'signin' || view === 'signup' || view === 'forgot-email') {
      const emailInput = document.querySelector('input[type="email"]');
      (emailInput as HTMLInputElement)?.focus();
    } else if (view === 'email-verification' || view === 'forgot-otp') {
      otpRefs.current[0]?.focus();
    }
  }, [view]);

  const generateAndSetOtp = () => {
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(code);
    return code;
  };

  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);
    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMsg('ESTABLISHING SECURE CONNECTION...');

    try {
      const user = await dbService.findUserByEmail(formData.email);
      if (!user) {
        setError('We couldn’t find an account with that email. Please check the spelling or create a new node.');
        return;
      }

      if ((user as any).password_hash !== formData.password) {
        setError('The password you entered is incorrect. Please try again or reset your key.');
        return;
      }

      if (!user.isEmailConfirmed) {
        setPendingUser(user);
        generateAndSetOtp();
        setView('email-verification');
      } else {
        const { password_hash, ...cleanUser } = user as any;
        await dbService.recordLogin(cleanUser.id);
        onSuccess(cleanUser);
      }
    } catch (err) {
      setError('A system malfunction occurred while verifying credentials.');
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMsg('PROVISIONING SECURE NODE...');

    try {
      const existing = await dbService.findUserByEmail(formData.email);
      if (existing) {
        setError('This email is already registered. Please sign in to your existing node.');
        return;
      }

      const newUser = await dbService.createUser(formData.username, formData.email, formData.password);
      setPendingUser(newUser);
      generateAndSetOtp();
      setView('email-verification');
    } catch (err) {
      setError('Node provisioning failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerification = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const code = otp.join('');
    if (code.length < 6) {
      setError('Please enter the complete 6-digit confirmation code.');
      return;
    }

    if (code === generatedOtp && pendingUser) {
      setLoading(true);
      await dbService.confirmEmail(pendingUser.id);
      setSuccessMsg('Account verified. Initializing session...');
      setTimeout(() => onSuccess({ ...pendingUser, isEmailConfirmed: true }), 1500);
    } else {
      setError('The code entered does not match our records. Please verify and try again.');
    }
  };

  const handleForgotEmail = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    const user = await dbService.findUserByEmail(formData.email);
    if (!user) {
      setError('We couldn’t find an account associated with this email.');
      setLoading(false);
    } else {
      generateAndSetOtp();
      setView('forgot-otp');
      setLoading(false);
    }
  };

  const handleForgotOtp = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (otp.join('') === generatedOtp) {
      setView('forgot-new');
    } else {
      setError('Invalid recovery code. Please check your inbox.');
    }
  };

  const handleResetPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (formData.password !== formData.confirmPassword) {
      setError('The passwords do not match. Please ensure both fields are identical.');
      return;
    }
    if (formData.password.length < 8) {
      setError('For your safety, passwords must be at least 8 characters long.');
      return;
    }
    setLoading(true);
    const success = await dbService.updateUserPassword(formData.email, formData.password);
    if (success) {
      setSuccessMsg('Your security key has been updated. Redirecting to login...');
      setTimeout(() => setView('signin'), 2000);
    } else {
      setError('We were unable to update your password at this time.');
    }
    setLoading(false);
  };

  const StatusDisplay = () => (
    <div className="mb-6 space-y-3">
      {error && (
        <div className="p-4 rounded-2xl bg-amber-500/5 border border-amber-500/20 text-amber-500 text-[11px] font-mono leading-relaxed animate-in fade-in slide-in-from-top-2">
          <span className="font-bold">[!] NOTICE:</span> {error}
        </div>
      )}
      {successMsg && (
        <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/20 text-emerald-400 text-[11px] font-mono flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
          <div className="w-5 h-5 rounded-full bg-emerald-500/20 flex items-center justify-center shrink-0">
            <svg className="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4">
              <polyline points="20 6 9 17 4 12" />
            </svg>
          </div>
          {successMsg}
        </div>
      )}
    </div>
  );

  if (view === 'choice') {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/95 backdrop-blur-md">
        <div className="w-full max-w-5xl flex flex-col items-center animate-in fade-in zoom-in-95 duration-700">
          <div className="text-center mb-16">
            <div className="flex justify-center mb-8">
              <div className="w-24 h-24 rounded-3xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center neon-glow shadow-inner group">
                <div className="scale-[2.8] text-emerald-400 group-hover:scale-[3] transition-transform duration-500">
                  <Icons.Shield />
                </div>
              </div>
            </div>
            <h1 className="text-4xl font-bold tracking-[0.2em] text-white mb-4 font-mono uppercase">
              DEFENDRA_VAULT
            </h1>
            <p className="text-slate-400 text-sm tracking-widest uppercase font-mono max-w-md mx-auto opacity-70">
              Identity verification required to establish secure buffer
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-10 w-full max-w-4xl">
            <button
              onClick={() => setView('signin')}
              className="group relative flex flex-col items-center text-center p-12 glass-card rounded-[3rem] transition-all duration-500 hover:neon-glow hover:-translate-y-2 border-emerald-500/10 hover:border-emerald-500/40"
            >
              <div className="mb-10 p-7 rounded-full bg-emerald-500/5 text-emerald-400 group-hover:bg-emerald-500 group-hover:text-slate-950 transition-all duration-500 shadow-inner">
                <div className="scale-[1.8]"><Icons.User /></div>
              </div>
              <h3 className="text-2xl font-bold font-mono tracking-widest text-white mb-4">AGENT_LOGIN</h3>
              <p className="text-xs text-slate-500 leading-relaxed font-mono opacity-80 uppercase tracking-widest">
                Full neural access<br/>Session persistence enabled
              </p>
            </button>

            <button
              onClick={onGuestChoice}
              className="group relative flex flex-col items-center text-center p-12 glass-card rounded-[3rem] transition-all duration-500 hover:neon-glow hover:-translate-y-2 border-slate-700/30 hover:border-emerald-500/20"
            >
              <div className="mb-10 p-7 rounded-full bg-slate-800/50 text-slate-400 group-hover:bg-white group-hover:text-slate-950 transition-all duration-500 shadow-inner">
                <div className="scale-[1.8]"><Icons.Zap /></div>
              </div>
              <h3 className="text-2xl font-bold font-mono tracking-widest text-slate-200 mb-4">GUEST_BYPASS</h3>
              <p className="text-xs text-slate-500 leading-relaxed font-mono opacity-80 uppercase tracking-widest">
                Ephemeral session<br/>Buffer purges on close
              </p>
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/98 backdrop-blur-2xl">
      <div className="w-full max-w-md glass-card rounded-[3rem] border-emerald-500/10 shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-8 duration-500">

        <div className="p-10 border-b border-emerald-500/5 text-center relative bg-emerald-500/[0.01]">
          <button 
            onClick={() => { setView('choice'); setError(''); setSuccessMsg(''); }}
            className="absolute left-8 top-1/2 -translate-y-1/2 text-slate-600 hover:text-emerald-400 transition-all hover:scale-110"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="w-5 h-5"><path d="M19 12H5M12 19l-7-7 7-7" /></svg>
          </button>

          <div className="flex justify-center mb-6">
            <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center text-emerald-400 border border-emerald-500/20 shadow-inner">
              <Icons.Shield />
            </div>
          </div>

          <h2 className="text-2xl font-bold font-mono tracking-widest text-white uppercase">
            {view === 'signin' && 'Secure Login'}
            {view === 'signup' && 'Create Account'}
            {view === 'email-verification' && 'Verify Email'}
            {view.startsWith('forgot') && 'Account Recovery'}
          </h2>
          <p className="text-[10px] text-emerald-500/40 mt-2 uppercase tracking-[0.3em] font-mono">
            {view === 'signin' ? 'Access your protected session' : 'Initialize security node'}
          </p>
        </div>

        <div className="p-10">
          <StatusDisplay />

          {view === 'signin' && (
            <form onSubmit={handleSignIn} className="space-y-6">
              <div className="space-y-4">
                <input
                  type="email"
                  required
                  className="w-full bg-slate-950/40 border border-slate-800 rounded-2xl px-5 py-4 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-700"
                  placeholder="EMAIL_ADDRESS"
                  value={formData.email}
                  onChange={e => setFormData({ ...formData, email: e.target.value })}
                />
                <input
                  type="password"
                  required
                  className="w-full bg-slate-950/40 border border-slate-800 rounded-2xl px-5 py-4 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-700"
                  placeholder="SECURITY_KEY"
                  value={formData.password}
                  onChange={e => setFormData({ ...formData, password: e.target.value })}
                />
              </div>
              <button type="submit" disabled={loading} className="w-full bg-emerald-500 text-slate-950 font-mono font-bold py-4 rounded-2xl transition-all hover:bg-emerald-400 active:scale-95 text-[11px] tracking-[0.2em] uppercase shadow-lg shadow-emerald-500/20">
                {loading ? 'AUTHENTICATING...' : 'Initiate Secure Login'}
              </button>
              <div className="flex flex-col gap-4 text-center mt-6">
                <button type="button" onClick={() => setView('signup')} className="text-[10px] font-mono uppercase text-slate-500 hover:text-emerald-400 tracking-widest">Create New Node</button>
                <button type="button" onClick={() => setView('forgot-email')} className="text-[10px] font-mono uppercase text-slate-500 hover:text-emerald-400 tracking-widest">Reset Security Key</button>
              </div>
            </form>
          )}

          {view === 'signup' && (
            <form onSubmit={handleSignUp} className="space-y-6">
              <div className="space-y-4">
                <input
                  type="text"
                  required
                  className="w-full bg-slate-950/40 border border-slate-800 rounded-2xl px-5 py-4 text-sm font-mono text-white focus:border-emerald-500/50 focus:outline-none transition-all placeholder:text-slate-700"
                  placeholder="AGENT_NAME"
                  value={formData.username}
                  onChange={e => setFormData({ ...formData, username: e.target.value })}
                />
                <input
